(function(){var m=window.SITE_DATA_BY_DOMAIN||{};var d=m["moe"]||{};var a=d["algorithms"]||[];for(var i=0;i<a.length;i++){if(a[i].id=="alg-chunked-prefill"){a[i]["long_html"]="<nav class=\"long-toc\"><b>本页目录</b><ol><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunked-prefill-sec-1\">一 · 事故现场：一次长预填如何把在线解码拖垮</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunked-prefill-sec-2\">二 · 它解决什么：把干扰上限变成可标定的旋钮</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunked-prefill-sec-3\">三 · 它不解决什么：三条边界要提前划清</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunked-prefill-sec-4\">四 · 适用边界的判定：什么负载该用它，什么负载不该</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunked-prefill-sec-5\">五 · 代价的定量形态：为什么 chunk 大小必须标定而不是拍脑袋</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunked-prefill-sec-6\">六 · 长预填独占下的 TPOT 击穿：piggyback 解决什么、不解决什么</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunked-prefill-sec-7\">七 · 切分：预填队列的 token 化与 chunk 记账</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunked-prefill-sec-8\">八 · 拼批：$B_{\\text{step}} = B_{\\text{decode}} + c_{\\text{chunk}}$ 的构成</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunked-prefill-sec-9\">九 · MoE 层：按 token 独立路由与混合 dispatch</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunked-prefill-sec-10\">十 · Attention：因果 mask 与 KV gather 的双路径</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunked-prefill-sec-11\">十一 · 落页与自回归：KV 写入 page 与 decode 续跑</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunked-prefill-sec-12\">十二 · 标定：chunk size 作为唯一的干扰旋钮</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunked-prefill-sec-13\">十三 · 混合批次的边界：chunk 标定、路由偏斜与每步代价</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunked-prefill-sec-14\">十四 · 统一批次的两项时间下界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunked-prefill-sec-15\">十五 · 批次构成的守恒式与 chunk 的干扰上限</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunked-prefill-sec-16\">十六 · 伪代码：可实现的调度与拆分</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunked-prefill-sec-17\">十七 · 混批路由偏斜的代价传导</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunked-prefill-sec-18\">十八 · 与分离部署的判据：同一份权重摊薄</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunked-prefill-sec-19\">十九 · 混批边界：从 $T_{\\text{step}}$ 的两项看 chunk 的可标定区间</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunked-prefill-sec-20\">二十 · chunk 标定的失效边界：从 $T_{\\text{step}}$ 的两项看干扰上限</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunked-prefill-sec-21\">二十一 · 请求形态：什么样的负载才吃这套配方</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunked-prefill-sec-22\">二十二 · 批内配比：decode 与预填的算力/带宽账</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunked-prefill-sec-23\">二十三 · 负载不对：三种典型失衡</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunked-prefill-sec-24\">二十四 · 标定方法：按 SLO 反解 chunk</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunked-prefill-sec-25\">二十五 · 与分离部署的负载分界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunked-prefill-sec-26\">二十六 · 负载配方：长预填与在线解码的混合比例决定成败</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunked-prefill-sec-27\">二十七 · 硬件档位与并行拓扑的耦合选择</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunked-prefill-sec-28\">二十八 · 量化方案的搭配与数值边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunked-prefill-sec-29\">二十九 · KV 策略与 page 池的容量标定</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunked-prefill-sec-30\">三十 · 调度参数的标定顺序</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunked-prefill-sec-31\">三十一 · 可复现的配置思路与稳定性校验</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunked-prefill-sec-32\">三十二 · 混批配方的失效边界：chunk 标定、专家热点与步进代价</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunked-prefill-sec-33\">三十三 · 单步时间账：带宽项与算力项谁在压顶</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunked-prefill-sec-34\">三十四 · 显存与 KV page：写入时机决定峰值</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunked-prefill-sec-35\">三十五 · 带宽摊薄的真实收益与它的上限</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunked-prefill-sec-36\">三十六 · 通信与功耗：混批把两种密集叠在同一时钟周期</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunked-prefill-sec-37\">三十七 · 规模上去以后哪里先崩：三条饱和线的排序</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunked-prefill-sec-38\">三十八 · 混批步的系统代价：带宽、专家热点与尾延迟的先后崩点</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunked-prefill-sec-39\">三十九 · 精度漂移：混批下的数值一致性诊断</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunked-prefill-sec-40\">四十 · OOM：KV page 与临时缓冲的双重压力</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunked-prefill-sec-41\">四十一 · 批抖动与路由不均：从 TPOT 方差定位到专家热点</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunked-prefill-sec-42\">四十二 · 尾延迟尖刺：chunk 边界与调度步对齐</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunked-prefill-sec-43\">四十三 · 监控面与回滚闸门</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunked-prefill-sec-44\">四十四 · 混批的失效边界：从路由偏斜到 chunk 标定失准</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunked-prefill-sec-45\">四十五 · 同族谱系：三条路线与一个共同分母</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunked-prefill-sec-46\">四十六 · 决策表：四个判据与三档结论</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunked-prefill-sec-47\">四十七 · 与分离部署的边界：共享前向的收益与代价</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunked-prefill-sec-48\">四十八 · 与整段独占的边界：时间片串行 vs 批次内配额</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunked-prefill-sec-49\">四十九 · 选型后的标定顺序与回退路径</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunked-prefill-sec-50\">五十 · 选型边界：piggyback 与整段预填、预填解码分离部署的三角权衡</button></li></ol></nav><figure class=\"diagram\" data-fig=\"algo-flow\"><svg style=\"max-width:504px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 503.6 352\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><rect x=\"58.0\" y=\"12.0\" width=\"421.6\" height=\"44.8\" rx=\"8\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"34.4\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"38.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">1</text><text x=\"75.0\" y=\"39.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">预填请求按 chunk size（如 512 token）切分，进入预填队列</text><line x1=\"82.0\" y1=\"58.8\" x2=\"82.0\" y2=\"75.8\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 74.8 L 86.5 74.8 L 82.0 82.8 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"82.8\" width=\"421.6\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"105.3\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"109.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">2</text><text x=\"75.0\" y=\"110.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">调度器每步取出 decode 批次 + 一个预填 chunk，拼成统一批次</text><line x1=\"82.0\" y1=\"129.7\" x2=\"82.0\" y2=\"146.7\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 145.7 L 86.5 145.7 L 82.0 153.7 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"153.7\" width=\"421.6\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"176.1\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"180.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">3</text><text x=\"75.0\" y=\"181.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">统一批次过 MoE 层，路由按 token 独立计算，预填 token 与…</text><line x1=\"82.0\" y1=\"200.5\" x2=\"82.0\" y2=\"217.5\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 216.5 L 86.5 216.5 L 82.0 224.5 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"224.5\" width=\"421.6\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"247.0\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"251.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">4</text><text x=\"75.0\" y=\"252.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">attention 对预填 token 用因果 mask、对 decode…</text><line x1=\"82.0\" y1=\"271.4\" x2=\"82.0\" y2=\"288.4\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 287.4 L 86.5 287.4 L 82.0 295.4 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"295.4\" width=\"421.6\" height=\"44.8\" rx=\"8\" fill=\"#e8f5ec\" stroke=\"#cde9d5\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"317.8\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"322.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">5</text><text x=\"75.0\" y=\"323.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">预填 chunk 完成后 KV 写入 page，decode token …</text></svg><figcaption><b>执行流程</b> · 从输入到输出的关键步骤；每一步的复杂度与坑在正文展开。</figcaption></figure>\n<h3 id=\"alg-chunked-prefill-sec-1\">一 · 事故现场：一次长预填如何把在线解码拖垮</h3>\n<p>设想一个已经跑稳的在线服务：解码批次稳定在几十个请求的量级，TPOT 落在 SLO 之内，GPU 的 SM 占用看上去也不难看。此时进来一个长上下文请求——一份需要整段读入的文档、一段多轮对话的历史回放，预填长度远超常规。调度器按最朴素的策略把它整段塞进下一个调度步：这一步的批次里，预填 token 数量级压过了解码 token 数量级。后果不是\"慢一点\"，而是三层同时塌陷。</p>\n<p>第一层是解码被饿死。整段预填占满 SM 与寄存器资源，原本该在每步执行的解码请求被推迟到预填结束之后，已经在途的解码请求 TPOT 出现尖峰，连续几个调度步的间隔被拉长到 SLO 之外。第二层是干扰不可控。预填是算力密集形态，解码是带宽密集形态——解码每步要为每个请求读取全部 KV 与全部专家权重，算术强度极低；预填则相反。两者被强行放进同一个前向时，预填的算力需求会把解码的带宽窗口挤掉，解码的每 token 成本随预填规模漂移，而不是稳定在一个可预测的值上。第三层是排队放大。被推迟的解码请求在队列里堆积，新到的短请求 TTFT 一起被拉长，于是 TTFT 与 TPOT 两个 SLO 同时失守——这正是这个算法要解决的具体问题：不是\"预填慢\"，而是长预填独占 GPU 造成解码饿死，且两类负载的密集形态在同一批次内互相干扰。</p>\n<p>把这个事故写成调度关系就很清楚。设 $B_{\\text{decode}}$ 为当前解码请求的 token 数，$c_{\\text{chunk}}$ 为每步注入的预填量，则一步的批次规模为</p>\n<div class=\"formula\">$$B_{\\text{step}} = B_{\\text{decode}} + c_{\\text{chunk}}$$</div>\n<p>整段预填等价于令 $c_{\\text{chunk}}$ 等于整个预填长度，$B_{\\text{step}}$ 被预填单方面决定，$B_{\\text{decode}}$ 在步内的占比趋近于零。步时则由带宽项与算力项取大者约束：</p>\n<div class=\"formula\">$$T_{\\text{step}}\\approx\\max\\left(\\frac{B_{\\text{dec}}N_{\\text{kv}}}{\\text{BW}},\\ \\frac{B_{\\text{dec}}+C_{\\text{chunk}}}{\\text{FLOPs}_{\\text{peak}}}\\right),\\quad \\text{TPOT}\\le \\frac{T_{\\text{step}}}{\\text{tokens/step}}$$</div>\n<p>事故的机理就藏在这个 max 里：$C_{\\text{chunk}}$ 一旦压过 $B_{\\text{dec}}N_{\\text{kv}}/\\text{BW}$ 对应的带宽项，步时由算力项主导，而算力项的分母是整卡峰值算力、分子被预填撑大，解码 token 摊到的有效算力被稀释。TPOT 的上界随 $C_{\\text{chunk}}$ 单调恶化，且恶化幅度不可由解码侧的任何参数抵消——解码请求自己无法把自己的 TPOT 拉回来，只能等预填结束。这就是\"饿死\"的定量含义。</p>\n\n<h3 id=\"alg-chunked-prefill-sec-2\">二 · 它解决什么：把干扰上限变成可标定的旋钮</h3>\n<p>这个算法的核心动作只有一句：把长预填切成固定大小的 chunk，每个调度步取\"当前全部解码请求 + 一个预填 chunk\"拼成统一批次，让解码 token 与预填 token 共享一次前向。切分之后，$c_{\\text{chunk}}$ 不再是请求给定的外生变量，而是调度器手里的内生参数，于是 $B_{\\text{step}}$ 的上界被钉住，预填对解码的干扰上限也随之被钉住。材料给出的 chunk size 示例是 512 token——这个数字的意义不在于它最优，而在于它把\"这一步最多有多少预填 token 与解码抢资源\"从\"取决于用户输入多长\"变成了\"取决于我们设了多少\"。</p>\n<p>由此 TTFT 与 TPOT 从一对互相绑架的指标变成两个可以分别调的方向：chunk 调大，预填推进快、TTFT 好，但每步对解码的挤压变重、TPOT 差；chunk 调小，TPOT 平稳，但预填被切得太碎、TTFT 变差。这正是它相对\"整段预填独占 GPU\"的差别——不是让预填更快，而是让预填的推进速度成为一个可交易的量。相对预填解码分离部署，它的差别同样明确：不拆 GPU 池，预填与解码仍共享同一前向与同一份专家权重，靠 chunk 大小而非资源隔离来控制干扰。分离部署把干扰变成资源竞争问题，本算法把干扰变成批次构成问题，代价与收益的形态完全不同。</p>\n<p>第二个收益来自权重读取的摊薄。解码每步必须把 MoE 专家权重从 HBM 搬到 SM，这部分带宽开销与批内 token 数几乎无关；把预填 chunk 塞进同一批次后，同一份权重读取同时服务两类 token，专家权重带宽被共同摊薄，GPU 利用率上升。注意这是\"摊薄\"而非\"减少\"：单步的权重流量不变，但摊到的有效 token 变多。工程上这意味着在解码批次偏小、权重带宽成为瓶颈的时段，混批能实打实提升每步产出；而在解码批次已经很大的时段，摊薄收益递减，混批的主要价值退回到干扰控制。</p>\n\n<h3 id=\"alg-chunked-prefill-sec-3\">三 · 它不解决什么：三条边界要提前划清</h3>\n<p>第一条边界是路由偏斜。统一批次过 MoE 层时，路由按 token 独立计算，预填 token 与解码 token 混合 dispatch——这一步不会因为混批而变得更均衡，反而更偏斜。预填 token 来自同一段长文档，语义集中，路由结果天然聚集到少数专家；解码 token 分散在多个请求上，分布另有一套。两者叠加后，热点专家的容量溢出概率上升，触发 token 丢弃或排队，混合 dispatch 的负载不均还会放大专家并行的通信开销。也就是说，本算法控制的是\"预填占多少算力\"，控制不了\"这些算力落到哪些专家上\"。容量因子路由、令牌丢弃、无丢弃块稀疏分组 GEMM 这些手段是另一条线上的事，本算法不与它们竞争，也不替代它们。</p>\n<p>第二条边界是 chunk 过小带来的固定开销。预填被切碎后，每个 chunk 都要独立走一遍 kernel launch、路由、dispatch 的固定路径；chunk 越小，调度步数越多而每步有效 token 越少，launch 开销在步时中的占比升高，GPU 利用率与 TTFT 同时恶化。这与\"chunk 调大拖慢解码\"构成一对反向约束：可行区间由 SLO 从两侧夹出来，而不是由某个通用最优值给定。材料明确说 chunk size 需按 SLO 精细标定，这句话的工程含义是：512 token 只是一个起点，真实部署里它必须跟着解码批次规模、专家并行度、SLO 松紧一起重标。</p>\n<p>第三条边界是规模上限。混批使路由偏斜，热点专家容量成为规模上限——当解码批次与预填 chunk 同时变大，偏斜的绝对量也变大，专家容量的余量被吃掉，此时继续加大 chunk 不会提升吞吐，只会把溢出概率推高。换句话说，这个算法在中等规模、SLO 双向约束的场景里收益最确定；当系统已经接近专家容量上限时，它是缓解手段而不是扩容手段。</p>\n\n<h3 id=\"alg-chunked-prefill-sec-4\">四 · 适用边界的判定：什么负载该用它，什么负载不该</h3>\n<p>判定可以落成三条可操作的检查。其一，看请求形态是否\"长预填与在线解码混合\"——如果服务里预填长度分布很窄、几乎没有长预填，整段预填不会造成饿死，切块的收益主要只剩权重摊薄，收益有限。其二，看 SLO 是否同时约束 TTFT 与 TPOT——只约束其中一个时，直接调 chunk 大小即可，不需要混批这套机制；两个都约束时，混批提供的\"分别调优\"才是刚需。其三，看解码批次是否长期偏小——解码批次大时权重带宽已被充分摊薄，混批的边际收益下降，而路由偏斜的代价照付。</p>\n<p>反过来，不该用它的场景也很清楚：预填与解码已经物理分离到不同 GPU 池的部署，干扰已由资源隔离解决，再引入混批只会把两边的批次构成搅在一起；专家容量已经吃紧、路由偏斜已是主要矛盾的部署，应先处理容量与路由，而不是加大混批规模；以及预填长度极短、chunk 切分后每块只剩几十个 token 的场景，launch 开销会直接吃掉全部收益。</p>\n<table class=\"mini\"><thead><tr><th>判定维度</th><th>倾向使用</th><th>倾向不用</th></tr></thead><tbody><tr><td>请求形态</td><td>长预填与在线解码混合</td><td>预填长度分布窄、无长预填</td></tr><tr><td>SLO 约束</td><td>TTFT 与 TPOT 同时约束</td><td>仅约束其一</td></tr><tr><td>解码批次</td><td>长期偏小、权重带宽成瓶颈</td><td>已足够大、摊薄收益递减</td></tr><tr><td>专家容量</td><td>有余量</td><td>已接近上限、路由偏斜为主矛盾</td></tr><tr><td>部署形态</td><td>预填解码共享同一前向</td><td>已做物理分离的 GPU 池</td></tr></tbody></table>\n<p>把这张表读成一句话：本算法处理的是\"同一份权重、同一张卡上，两类密集形态的负载如何共存\"这个问题；一旦这个问题被别的机制（资源隔离、容量扩容、路由改造）消解，它就不再是最优解。它的适用边界不是由模型规模划的，而是由\"干扰是否发生在同一前向内\"划的。</p>\n\n<h3 id=\"alg-chunked-prefill-sec-5\">五 · 代价的定量形态：为什么 chunk 大小必须标定而不是拍脑袋</h3>\n<p>把代价写成可标定的形式，才能解释为什么 512 这个数字不能照抄。设单步预填推进量为 $c_{\\text{chunk}}$，则预填一个长度为 $L$ 的请求需要的步数为 $\\lceil L/c_{\\text{chunk}}\\rceil$，TTFT 大致随这个步数线性增长；而解码侧每步的 TPOT 上界由前面的 $T_{\\text{step}}$ 给出，随 $c_{\\text{chunk}}$ 单调上升。两个方向一个要小、一个大，交点就是 SLO 允许的 chunk 区间。若把 chunk 设得过大，单步预填 token 数压过解码批次，解码 TPOT 被预填算力拖慢，长预填请求仍会周期性击穿延迟 SLO——事故并没有被消除，只是从\"一次长尖峰\"变成\"周期性尖峰\"。若设得过小，launch 开销占比升高，调度步数增多而每步有效 token 减少，GPU 利用率与 TTFT 同时恶化。两侧都是真实的失败模式，不是理论担忧。</p>\n<p>还有一个容易被忽略的代价项：混批后 MoE 路由分布偏斜，热点专家容量溢出触发丢弃或排队，混合 dispatch 的负载不均放大专家并行通信开销。这一项不体现在 $T_{\\text{step}}$ 的公式里，却直接体现在尾延迟上——容量溢出是概率事件，它把 TPOT 的分布拉出长尾，而 SLO 通常约束的是尾部分位数。所以 chunk 标定不能只看均值步时，必须把专家容量余量作为约束一起解。</p>\n<p>工程判断落在这里：chunk size 是一个需要跟解码批次规模、专家并行度、SLO 分位数三者一起标定的参数，且标定结果随负载配方漂移，需要周期性重标而不是一次设定。把 512 token 当作默认值可以，把它当作常量不行。真正决定这个算法能否稳住 SLO 的，不是切块这个动作本身，而是切块大小与当前批次构成、专家容量余量之间的匹配关系——这也是后续调度步拼接、输出按来源拆分等机制要承接的起点。</p>\n\n<h3 id=\"alg-chunked-prefill-sec-6\">六 · 长预填独占下的 TPOT 击穿：piggyback 解决什么、不解决什么</h3>\n<p>线上最典型的失败形态不是平均延迟超标，而是延迟的周期性尖峰。一个长上下文请求（例如一次数万 token 的文档问答或代码库分析）进入调度器后，若按整段预填独占 GPU，则在其预填完成之前，所有在线 decode 请求都拿不到 SM 与权重带宽：这些请求的 TPOT 被拉长到与预填时长同量级，而它们的 SLO 只约束单 token 间隔。工程上表现为 TTFT 与 TPOT 两个指标互相拉扯——把预填优先级调高，TTFT 达标而 TPOT 尖峰击穿；把 decode 优先级调高，长预填被无限推迟，TTFT 崩溃。piggyback 针对的正是这个具体矛盾：它不减少预填的总计算量，也不改变单请求的算术强度，而是把长预填切成固定 chunk，与当前 decode 批次拼成统一批次，使预填对 decode 的干扰有一个可标定的上限。</p>\n<p>其调度关系可以写成一条极简的账：</p>\n<div class=\"formula\">$$B_{\\text{step}} = B_{\\text{decode}} + c_{\\text{chunk}},\\quad T_{\\text{step}}\\approx\\max\\left(\\frac{B_{\\text{dec}}N_{\\text{kv}}}{\\text{BW}},\\ \\frac{B_{\\text{dec}}+C_{\\text{chunk}}}{\\text{FLOPs}_{\\text{peak}}}\\right)$$</div>\n<p>其中 $c_{\\text{chunk}}$ 是每步注入的预填 token 数（材料给出的示例为 512 token）。这条式子说明边界所在：chunk 越大，单步的算力项越占主导，decode 的 TPOT 被预填拖慢的幅度越大；chunk 越小，单步有效 token 越少，预填 kernel launch 开销与调度步数占比上升，TTFT 与 GPU 利用率同时恶化。因此 piggyback 的收益不是无条件的，它把“预填独占”的粗粒度冲突换成了“chunk 标定”的细粒度权衡，代价是必须按 SLO 精细标定，且标定结果对负载配方敏感。</p>\n<p>它明确不解决的问题有三类。第一，资源隔离类问题：与预填/解码分离部署不同，piggyback 不拆分 GPU 池，预填与解码共享同一次前向与同一份 MoE 专家权重，因此当预填 chunk 与 decode token 混批后路由分布偏斜、热点专家容量溢出时，触发的是 token 丢弃或排队，混合 dispatch 的负载不均还会放大专家并行通信开销——这类溢出无法靠调 chunk 消除，只能靠专家容量与路由策略消化，它构成该方案的规模上限。第二，单请求内部的延迟问题：一个超长预填请求自身的 TTFT 仍由 chunk 数乘以步数决定，piggyback 不让它更快，只让它不再阻塞别人。第三，带宽侧的根本约束：decode 的 KV gather 带宽需求不因混批而下降，混批只是把权重读取摊薄，KV page 的读写压力依旧按 $B_{\\text{dec}}N_{\\text{kv}}$ 增长。一个具体判断是：当在线 decode 批次本身已接近带宽上限时，再注入 512 token 的预填 chunk 只会让 $T_{\\text{step}}$ 的带宽项饱和、算力项空转，此时应缩小 chunk 或退回分离部署，而不是继续加大 chunk 追求 TTFT。</p>\n<h3 id=\"alg-chunked-prefill-sec-7\">七 · 切分：预填队列的 token 化与 chunk 记账</h3>\n<p>机制的第一步不是调度，而是把一条长预填请求从“一个不可分割的作业”变成“一串可插队的 token 段”。预填请求进入系统时，其 prompt 长度 $L_p$ 被按固定 chunk size $c_{\\text{chunk}}$（材料给出的锚点是 512 token）切成 $\\lceil L_p / c_{\\text{chunk}} \\rceil$ 个段，每段携带自己的 token 区间、位置偏移与因果 mask 边界，依次压入预填队列。这一步的输入是请求的完整 token 序列与 KV 目标页表，输出是一组带序号的 chunk 描述符；代价是纯记账开销——不触碰 GPU 算力，但要求调度器为每个 chunk 维护“已写入 KV 的 token 数”这一游标，因为后续 chunk 的 attention 必须能看到前序 chunk 已落页的 KV。</p>\n<p>切分的工程含义在于把 TTFT 从“整段预填完成”解耦为“首个 chunk 完成即可出第一个 token 的前置条件”。一条 $L_p$ 很长的请求，其 TTFT 不再由 $L_p$ 决定，而由排队位置与 $c_{\\text{chunk}}$ 决定；代价是这条请求的 KV 写入被拉长到多个调度步，中间态必须可恢复。若 chunk 描述符只记 token 区间而不记 KV 页归属，后续 chunk 的 attention 会读到未初始化页，这是切分阶段最典型的正确性陷阱。</p>\n<p>切分粒度的选择直接决定后面所有步骤的代价结构。$c_{\\text{chunk}}$ 越小，预填队列的条目越多、调度步数越多，每步注入的预填算力越平滑；$c_{\\text{chunk}}$ 越大，单步预填 token 数越接近整段预填，decode 被拖慢的风险回升。材料给出的 512 token 是一个在 kernel launch 开销与干扰上限之间取平衡的示例值，而非普适常数。</p>\n\n<h3 id=\"alg-chunked-prefill-sec-8\">八 · 拼批：$B_{\\text{step}} = B_{\\text{decode}} + c_{\\text{chunk}}$ 的构成</h3>\n<p>调度器每个调度步做一次拼批：取当前所有活跃 decode 请求的 token（每条 decode 请求每步通常贡献 1 个 token，故 $B_{\\text{decode}}$ 近似等于活跃 decode 序列数），再加上预填队列头部的一个 chunk，构成统一批次：</p>\n<div class=\"formula\">$$B_{\\text{step}} = B_{\\text{decode}} + c_{\\text{chunk}}$$</div>\n<p>输入是 decode 活跃集与预填队列头；输出是一个混合了两种来源 token 的批次张量，附带每个 token 的来源标签（prefill / decode）与其在序列中的位置。这一步的代价是调度决策本身的延迟，量级远小于一次前向，但它决定了本步的算力构成：$B_{\\text{decode}}$ 部分是带宽密集的（每 token 只做一次权重读取、KV gather 为主），$c_{\\text{chunk}}$ 部分是算力密集的（$c_{\\text{chunk}}$ 个 token 对已落页 KV 做因果 attention，矩阵乘规模随 chunk 线性增长）。</p>\n<p>拼批的实质是把两类负载塞进同一次权重读取。若不拼批，decode 步要单独读一遍专家权重，预填步再读一遍，MoE 专家权重的带宽被读两次；拼批后一次前向同时服务两类 token，专家权重带宽被 $B_{\\text{step}}$ 个 token 共同摊薄。这是该机制相对“预填独占 GPU”最直接的收益来源，也是相对“预填解码分离部署”的分野——后者靠拆 GPU 池做资源隔离，本机制不拆池，靠 chunk 大小控制干扰上限。</p>\n<p>拼批的硬约束是 $c_{\\text{chunk}}$ 不能压过 $B_{\\text{decode}}$。一旦单步预填 token 数远大于 decode 批次，本步的算力项被预填主导，decode 的 TPOT 被预填的矩阵乘拖慢，长预填请求仍会周期性击穿延迟 SLO。材料把这一失败模式明确列为 chunk size 标定过大的后果。</p>\n\n<h3 id=\"alg-chunked-prefill-sec-9\">九 · MoE 层：按 token 独立路由与混合 dispatch</h3>\n<p>统一批次进入 MoE 层后，路由按 token 独立计算——预填 token 与 decode token 各自算自己的 gate 分数、各自选专家，互不感知对方存在。这一步的输入是 $B_{\\text{step}}$ 个 token 的隐状态，输出是每个 token 的专家分配与容量因子约束下的 dispatch 计划。代价出现在 dispatch 阶段：两类 token 混合后，专家命中分布比纯 decode 批次更偏斜，热点专家的容量溢出概率上升，触发 token 丢弃或排队，而专家并行的 all-to-all 通信量随负载不均被放大。</p>\n<p>这里的机制细节是：decode token 的隐状态来自上一步自回归输出，分布相对集中；预填 token 的隐状态来自原始 prompt，语义跨度大，路由结果天然更分散。两者混在同一批次里做 top-k 选择，等于把两种分布叠在一起，热点专家的瞬时负载高于任一单独来源。容量因子路由与令牌丢弃的具体策略属于相邻条目，此处只需指出：混批使容量溢出的概率上升，是本机制规模上限的直接来源。</p>\n<p>工程上的缓解手段不是改路由，而是控制 $c_{\\text{chunk}}$ 与 $B_{\\text{decode}}$ 的比例，使预填 token 在批次中的占比不至于让路由分布过度偏斜。代价是这一比例必须按实际负载标定，无法用固定常数覆盖所有 SLO 场景。</p>\n\n<h3 id=\"alg-chunked-prefill-sec-10\">十 · Attention：因果 mask 与 KV gather 的双路径</h3>\n<p>attention 阶段是两种 token 真正分道的地方。预填 chunk 内的 token 对前序已落页 KV 与本 chunk 内前序 token 做因果 attention，mask 是标准的下三角加跨 chunk 的历史可见性；decode token 则对整条序列的 KV 做 gather，取自己需要的页。输入是统一批次的 query 与按页组织的 KV cache，输出是按来源拆分的两份 attention 结果。代价在这一步最集中：预填 chunk 的 attention 计算量随 $c_{\\text{chunk}}$ 增长，decode 的 KV gather 是纯带宽操作，两者在同一 kernel 内并行时，SM 的算力与带宽资源被同时占用。</p>\n<p>按来源拆分输出是正确性要求而非优化。若把两类 token 的 attention 输出混在一个张量里不回标来源，后续的 KV 写入与自回归采样会张冠李戴：预填 token 的输出不应进入采样，decode token 的输出不应被当作 KV 写入。拆分动作本身开销很小，但漏掉它会让整个混批机制失效。</p>\n<p>这一步的代价可以用单步时间下界刻画：</p>\n<div class=\"formula\">$$T_{\\text{step}}\\approx\\max\\left(\\frac{B_{\\text{dec}}N_{\\text{kv}}}{\\text{BW}},\\ \\frac{B_{\\text{dec}}+C_{\\text{chunk}}}{\\text{FLOPs}_{\\text{peak}}}\\right),\\quad \\text{TPOT}\\le \\frac{T_{\\text{step}}}{\\text{tokens/step}}$$</div>\n<p>第一项是 decode 侧 KV 带宽项，第二项是算力项。$c_{\\text{chunk}}$ 增大时第二项上升，一旦它超过第一项，单步时间被算力主导，decode 的 TPOT 随之上抬。这就是“chunk 过大则 decode 被拖慢”的定量形态。</p>\n\n<h3 id=\"alg-chunked-prefill-sec-11\">十一 · 落页与自回归：KV 写入 page 与 decode 续跑</h3>\n<p>预填 chunk 的 attention 输出经 FFN 后得到该 chunk 的 KV，按 page 为单位写入 KV cache，游标前移 $c_{\\text{chunk}}$。输入是本 chunk 的 KV 张量与页表分配结果，输出是更新后的页表与可被后续 chunk 和 decode gather 到的历史 KV。代价是页分配的碎片化风险：chunk 按 512 token 切分，若页大小与 chunk 不整除，每个 chunk 末尾会产生部分填充页，长 prompt 的页数随 chunk 数增长而膨胀，KV 显存占用上升。</p>\n<p>decode token 在同一批次里完成一次前向后继续自回归，其新生成的 KV 同样落页，供下一步 gather。预填队列清空之前，每个调度步都重复“拼批—MoE—attention—落页”这一循环；队列清空后，调度退化为纯 decode 批次，混批机制自然退出。这一退出条件是机制稳定的关键：若预填队列长期非空（持续有长请求到达），decode 批次将长期与预填 chunk 共存，TPOT 的抖动虽被 $c_{\\text{chunk}}$ 限住上限，但均值被抬高。</p>\n<p>落页阶段的工程判断是：页大小、chunk size 与 KV 显存三者必须联合标定。$c_{\\text{chunk}}$ 过小不仅增加 kernel launch 开销占比，还因页填充浪费推高显存；$c_{\\text{chunk}}$ 过大则单步预填 token 数压过 decode 批次。材料给出的 512 token 示例值应被视为标定起点，而非部署常数。</p>\n\n<h3 id=\"alg-chunked-prefill-sec-12\">十二 · 标定：chunk size 作为唯一的干扰旋钮</h3>\n<p>把上述步骤串起来看，整个机制只有一个可调旋钮：$c_{\\text{chunk}}$。它同时决定预填队列的条目数、单步注入的预填算力、MoE 路由的偏斜程度、页填充浪费的比例，以及 kernel launch 开销在单步时间中的占比。TTFT 通过“首个 chunk 何时被调度”受 $c_{\\text{chunk}}$ 影响，TPOT 通过“每步预填算力占比”受 $c_{\\text{chunk}}$ 影响，两者可分别调优但共用同一个参数，这是本机制相对资源隔离方案的结构性代价。</p>\n<p>标定的失败模式有三条，均已在材料中给出：chunk 过大使单步预填 token 数压过 decode 批次，decode 的 TPOT 被预填算力拖慢，长预填请求仍周期性击穿延迟 SLO；chunk 过小使预填 kernel launch 开销占比升高，调度步数增多而每步有效 token 减少，GPU 利用率与 TTFT 同时恶化；混批使 MoE 路由分布偏斜，热点专家容量溢出触发丢弃或排队，混合 dispatch 的负载不均放大专家并行通信开销。</p>\n<p>因此标定的正确姿势不是找“最优 chunk size”，而是按 SLO 反解可行区间：先由 TPOT 上限确定 $c_{\\text{chunk}}$ 的上界（保证算力项不超过带宽项主导），再由 TTFT 上限与 kernel launch 开销确定下界，最后在区间内按热点专家容量余量做二次收缩。区间为空即说明该负载配方不适合混批机制，应转向预填解码分离部署。</p>\n\n<h3 id=\"alg-chunked-prefill-sec-13\">十三 · 混合批次的边界：chunk 标定、路由偏斜与每步代价</h3>\n<p>把预填 chunk 塞进 decode 批次，本质是在同一个调度步里让两类 token 共享一次权重读取，因此每一步的耗时不是两类负载的简单相加，而是被两条资源通道分别约束。可用下面的上界刻画：<div class=\"formula\">$$T_{\\text{step}}\\approx\\max\\left(\\frac{B_{\\text{dec}}N_{\\text{kv}}}{\\text{BW}},\\ \\frac{B_{\\text{dec}}+C_{\\text{chunk}}}{\\text{FLOPs}_{\\text{peak}}}\\right),\\quad \\text{TPOT}\\le \\frac{T_{\\text{step}}}{\\text{tokens/step}}$$</div>其中 $B_{\\text{dec}}$ 是当前 decode 请求的 token 数，$C_{\\text{chunk}}$ 是每步注入的预填 chunk 大小，$N_{\\text{kv}}$ 是 decode 每 token 需要 gather 的 KV 规模。第一项是 decode 的带宽通道，第二项是预填的算力通道。当 $C_{\\text{chunk}}$ 远小于 $B_{\\text{dec}}$ 时，$T_{\\text{step}}$ 由带宽项主导，预填几乎是“搭便车”；一旦 $C_{\\text{chunk}}$ 增大到使算力项超过带宽项，预填就从搭车者变成拖车者，decode 的 TPOT 被直接拉长。这就是 chunk size 必须按 SLO 标定的根本原因——它决定的是两条通道中哪一条成为瓶颈，而不是一个可以随手取值的经验常数。材料给出的 512 token 只是一个起点，真实标定要对着 $B_{\\text{dec}}$ 的在线分布做。</p>\n<p>失效条件可以按 chunk 的两个方向拆开看。chunk 过大时，单步预填 token 数压过 decode 批次，算力项接管 $T_{\\text{step}}$，decode 的 TPOT 被预填算力拖慢，长预填请求仍会周期性击穿延迟 SLO——注意这里的“周期性”来自预填队列的持续注入，只要队列不清空，每个调度步都会重复一次击穿。chunk 过小时，预填 kernel launch 开销占比升高，调度步数增多而每步有效 token 减少，GPU 利用率与 TTFT 同时恶化：预填被切得太碎，启动开销和调度开销吃掉本应摊薄的权重读取收益，TTFT 反而比整段预填更差。两个方向都不是单调改善，存在一个由 $B_{\\text{dec}}$ 分布、kernel 启动开销和 SLO 共同决定的窄窗口。工程上判断窗口位置的办法不是调参试错，而是把 $T_{\\text{step}}$ 的两项分别打点，看哪一项在 SLO 约束下先触顶。</p>\n<p>更隐蔽的边界在 MoE 层。统一批次过 MoE 时路由按 token 独立计算，预填 token 与 decode token 混合 dispatch，这使路由分布比纯 decode 批次更偏斜：预填 chunk 来自同一段长文本，token 语义集中，容易把一批 token 压到少数专家上；decode token 则分散在多条请求上，分布本就较平。两者混在一起，热点专家的容量溢出概率上升，触发 token 丢弃或排队，而混合 dispatch 的负载不均又会放大专家并行的通信开销。这一代价不体现在 $T_{\\text{step}}$ 的公式里，却直接吃掉“共享一次权重读取”带来的带宽摊薄收益。规模上限因此不在 chunk size 本身，而在热点专家的容量：当预填 chunk 的语义集中度足以打爆某个专家时，加大 chunk 只会让溢出更频繁。稳定性技巧是按来源拆分输出以避免 mask 混淆，但路由偏斜无法靠拆分解决，只能靠 chunk 内容的分层或专家容量的冗余来吸收。</p>\n<p>与预填解码分离部署相比，这套方案的边界在于它不拆分 GPU 池，预填与解码共享同一前向与同一份专家权重，靠 chunk 大小而非资源隔离来控制干扰。这意味着它适合 decode 批次足够大、带宽项有余量的场景；一旦 decode 请求稀疏、$B_{\\text{dec}}$ 很小，预填 chunk 无论怎么切都会在算力项上压过 decode，此时混批的收益消失，分离部署反而更稳。反过来，在 decode 批次饱满、专家权重带宽是主要成本的场景里，piggyback 的摊薄效应最明显。判断标准是 $B_{\\text{dec}}N_{\\text{kv}}/\\text{BW}$ 与 $(B_{\\text{dec}}+C_{\\text{chunk}})/\\text{FLOPs}_{\\text{peak}}$ 的相对大小随在线负载的漂移方向，而不是固定的 chunk 数值。</p>\n<h3 id=\"alg-chunked-prefill-sec-14\">十四 · 统一批次的两项时间下界</h3>\n<p>把预填 chunk 与 decode 拼成一步之后，单步时间不再由任一来源单独决定，而是被两条资源路径夹住：一条是 decode 必须搬运的 KV 字节，另一条是整批 token 要过的算力。写成</p>\n<div class=\"formula\">$$T_{\\text{step}}\\approx\\max\\left(\\frac{B_{\\text{dec}}N_{\\text{kv}}}{\\text{BW}},\\ \\frac{B_{\\text{dec}}+C_{\\text{chunk}}}{\\text{FLOPs}_{\\text{peak}}}\\right),\\quad \\text{TPOT}\\le \\frac{T_{\\text{step}}}{\\text{tokens/step}}$$</div>\n<p>逐项看：$B_{\\text{dec}}$ 是当前 decode 请求的 token 数，$N_{\\text{kv}}$ 是每 token 需读取的 KV 字节（层数×头数×头维×2×精度字节），$\\text{BW}$ 是有效 HBM 带宽，$C_{\\text{chunk}}$ 是每步注入的预填 chunk 大小，$\\text{FLOPs}_{\\text{peak}}$ 是当前并行拓扑下的有效算力。第一项是带宽下界——decode 每步都要把历史 KV 从 HBM 拉进 SM，这部分与预填无关，是硬地板；第二项是算力下界——预填 token 与 decode token 一起过权重矩阵，FLOPs 随 $C_{\\text{chunk}}$ 线性上升。</p>\n<p>推导的关键一步在“取 max 而非相加”。两条路径在硬件上并行：decode 的 KV gather 走 HBM 读，预填的 GEMM 走 Tensor Core，只要调度把访存与计算交错排布，二者可重叠；但重叠的上限由较长的那条决定。因此 $C_{\\text{chunk}}$ 增大时，第二项线性抬高，一旦越过第一项，TPOT 就被预填算力拖住——这正是 chunk 过大击穿延迟 SLO 的数学形态。反之 $C_{\\text{chunk}}$ 趋零，第一项主导，TPOT 回到纯 decode 地板，但每步有效 token 只剩 decode，TTFT 被拉长。</p>\n<p>工程代价直接可读：以 512 token 的 chunk 为例，若 decode 批次为数百 token，第二项中的 $C_{\\text{chunk}}$ 已与 $B_{\\text{dec}}$ 同量级，意味着预填贡献了约一半的算力负载；此时若 $\\text{FLOPs}_{\\text{peak}}$ 因专家并行通信或路由偏斜被打折，第二项会先于第一项成为瓶颈，TPOT 抖动从“偶发”变为“周期性”。容量规划时应把 $C_{\\text{chunk}}$ 当作 TPOT 的调节旋钮，而不是吞吐旋钮。</p>\n\n<h3 id=\"alg-chunked-prefill-sec-15\">十五 · 批次构成的守恒式与 chunk 的干扰上限</h3>\n<p>调度侧的核心关系是一条加法守恒：</p>\n<div class=\"formula\">$$B_{\\text{step}} = B_{\\text{decode}} + c_{\\text{chunk}}$$</div>\n<p>$B_{\\text{decode}}$ 随在线请求数波动，$c_{\\text{chunk}}$ 由调度器固定。这条式子的意义不在求和，而在“上限”：预填对 decode 的干扰被 $c_{\\text{chunk}}/B_{\\text{step}}$ 这个比例封顶。若把 $c_{\\text{chunk}}$ 固定为 512，则无论预填队列里堆了多少长请求，单步注入的预填 token 不会超过 512，decode 侧看到的算力挤占有一个确定上界。这就是“用 chunk 大小控制干扰上限”的定量含义——它把不可预测的长预填突发，转换成可预测的固定配额。</p>\n<p>由此可推出 TTFT 的一阶估计：预填队列长度为 $L_{\\text{pre}}$（token），每步消化 $c_{\\text{chunk}}$，则一个长请求的预填完成步数约为 $\\lceil L_{\\text{pre}}/c_{\\text{chunk}}\\rceil$，TTFT 近似为该步数乘以 $T_{\\text{step}}$。这里出现一个反直觉的耦合：减小 $c_{\\text{chunk}}$ 降低了每步对 decode 的干扰（利于 TPOT），却增加了步数（不利于 TTFT）；增大 $c_{\\text{chunk}}$ 反之。二者不能同时最优，必须按 SLO 分配权重。</p>\n<p>具体例子：一条 8K token 的预填请求，按 512 切分需 16 步完成；若每步 $T_{\\text{step}}$ 被 decode 的 KV 带宽下界主导，则这 16 步的墙钟时间就是该请求的 TTFT 主体。与此同时，这 16 步内每步都夹带一个 512 token 的 chunk，decode 侧的 TPOT 上限由第一节的 max 式给出。调度器的任务就是在这条守恒式下，让两个 SLO 都不被击穿——这也是为什么 chunk size 必须“精细标定”而非取默认值。</p>\n\n<h3 id=\"alg-chunked-prefill-sec-16\">十六 · 伪代码：可实现的调度与拆分</h3>\n<p>把机制落到可实现层面，调度循环的形状如下（伪代码，非 <code>pre</code> 块）：</p>\n<ul>\n<li>初始化：prefill_queue 存待处理请求，decode_set 存活跃 decode 请求，c_chunk 取标定值（示例 512）。</li>\n<li>每步：从 decode_set 收集本步 decode token，得 B_decode；若 prefill_queue 非空，取队首请求切出至多 c_chunk 个 token 作为本步 chunk；拼成统一批次，记来源标签。</li>\n<li>前向：统一批次过 MoE 层，路由按 token 独立计算，预填 token 与 decode token 混合 dispatch；attention 分支——预填 token 走因果 mask，decode token 走 KV gather。</li>\n<li>输出拆分：按来源标签把 logits 分开，decode 部分采样并自回归，预填部分只取 KV。</li>\n<li>写回：预填 chunk 完成后，其 KV 按 page 写入分页 KV 池；若该请求预填未完成，剩余 token 留在队首等待下一步。</li>\n<li>终止条件：prefill_queue 清空且 decode_set 稳定，或达到调度步上限。</li>\n</ul>\n<p>关键实现细节有三处。其一，来源标签必须贯穿整个前向，否则 mask 混淆会让 decode token 误读预填 token 的 KV，输出错乱；这是“按来源拆分输出”的真正作用，不只是统计。其二，chunk 切分要按请求边界对齐，一个 chunk 不应跨两个请求，否则 KV page 写入的归属判断变复杂。其三，混合 dispatch 后 MoE 的容量因子需按混合后的路由分布重算，而非沿用纯 decode 的分布——这正是混批使路由偏斜的入口。</p>\n<p>系统代价体现在 kernel launch：chunk 过小时，每步的有效 token 少，但 launch 次数不变，launch 开销占比升高，调度步数增多而每步产出下降，GPU 利用率与 TTFT 同时恶化。这是伪代码层面无法回避的固定成本，只能靠 chunk 下限约束。</p>\n\n<h3 id=\"alg-chunked-prefill-sec-17\">十七 · 混批路由偏斜的代价传导</h3>\n<p>预填 token 与 decode token 的分布不同：预填 token 来自长文档的连续片段，decode token 是各请求当前步的单个 token，二者在 MoE 路由上的专家命中分布并不一致。混批后，路由按 token 独立计算，但容量因子是全局的，热点专家在混合分布下的溢出概率高于任一单独分布。溢出触发 token 丢弃或排队，直接表现为该步的有效算力打折，第一节公式中的 $\\text{FLOPs}_{\\text{peak}}$ 被隐性降低。</p>\n<p>代价传导路径清晰：路由偏斜 → 热点专家排队 → 专家并行 All-to-All 通信量不均 → 单步时间被最长的那条专家链路拖住 → TPOT 抖动放大。这与 chunk 过大造成的算力挤占是两种不同机理：前者是负载不均，后者是总量超标。工程判断上，前者靠容量因子与路由均衡缓解，后者靠 chunk size 上限约束，二者需分别标定。</p>\n<p>具体例子：512 token 的预填 chunk 若恰好落在某类高频 token 上，其路由会集中到少数专家，而同步的 decode token 也命中同一批专家，则该步这些专家的容量被双重占用，溢出概率上升；若 chunk 来自另一分布，则偏斜被摊薄。这说明 chunk 的内容分布本身就是一个隐变量，调度器无法完全控制，只能通过 chunk 大小限制单步注入量来限制最坏偏斜幅度。</p>\n\n<h3 id=\"alg-chunked-prefill-sec-18\">十八 · 与分离部署的判据：同一份权重摊薄</h3>\n<p>本机制不拆 GPU 池，预填与解码共享同一前向与同一份专家权重。这意味着每步的权重读取被两类 token 共同摊薄：纯 decode 时权重带宽只服务少量 token，利用率低；混批后预填 token 填满算力空档，权重读取的摊销分母变大。这是它相对预填解码分离部署的核心优势——分离部署用资源隔离换干扰可控，但两份权重、两套 KV 池，显存与带宽成本翻倍；本机制用 chunk 大小换干扰可控，成本是路由偏斜与 launch 开销。</p>\n<p>判据可写成定性比较：当 decode 批次足够大、权重带宽已被充分利用时，混批的摊薄收益消失，分离部署的隔离优势占优；当 decode 批次小、GPU 利用率不足时，混批的摊薄收益显著，且 chunk 上限能兜住 TPOT。规模上限则落在热点专家容量：混批使路由偏斜，专家并行度越高，偏斜放大的通信代价越难摊薄，这是该机制无法靠调 chunk 解决的硬边界。</p>\n<p>最后落在工程判断上：chunk size 的标定不是单点最优，而是一条在 TTFT 与 TPOT 之间的帕累托前沿；512 token 只是材料给出的示例锚点，实际取值应由第一节 max 式中两项的相对大小决定——当带宽项主导时 chunk 可放大以提升摊薄，当算力项主导时必须收紧以保住 TPOT。标定的产物应是一张按 decode 批次规模分档的 chunk 表，而非一个全局常数。</p>\n\n\n<h3 id=\"alg-chunked-prefill-sec-19\">十九 · 混批边界：从 $T_{\\text{step}}$ 的两项看 chunk 的可标定区间</h3>\n<p>把 $B_{\\text{step}} = B_{\\text{decode}} + c_{\\text{chunk}}$ 代回核心式，得到本方案真正可操作的两个约束。第一项 $\\frac{B_{\\text{dec}}N_{\\text{kv}}}{\\text{BW}}$ 是 KV 带宽项：$N_{\\text{kv}}$ 是每 token 需 gather 的 KV 字节数，它只由 $B_{\\text{decode}}$ 决定，注入预填 chunk 不改变这一项的分子——这是 piggyback 之所以能“免费”搭车的物理基础，预填 token 走因果 mask、不做 KV gather，因此不额外吃 HBM 带宽。第二项 $\\frac{B_{\\text{dec}}+C_{\\text{chunk}}}{\\text{FLOPs}_{\\text{peak}}}$ 才是 chunk 的直接代价：$C_{\\text{chunk}}$ 是 chunk 内实际参与矩阵乘的 token 数（含 padding 到 tile 边界的浪费），它与 $B_{\\text{decode}}$ 线性相加，意味着 chunk 每增大一倍，算力项的分母不变而分子抬升，$T_{\\text{step}}$ 的瓶颈会从带宽项切换到算力项。关键的一步推导在于：令两项相等可解出临界 chunk，$c^\\*_{\\text{chunk}} \\approx \\frac{B_{\\text{dec}}N_{\\text{kv}}\\cdot\\text{FLOPs}_{\\text{peak}}}{\\text{BW}} - B_{\\text{dec}}$，当 $c_{\\text{chunk}} &lt; c^\\*$ 时该步仍是带宽受限、预填近乎白搭；越过 $c^\\*$ 后预填开始直接拉长 $T_{\\text{step}}$，而 $\\text{TPOT} \\le T_{\\text{step}}/(\\text{tokens/step})$ 中的 tokens/step 只计 decode token，于是 TPOT 被预填算力按比例拖慢。512 token 的示例值之所以常见，是因为它通常落在 $c^\\*$ 附近偏下的位置：既让预填 kernel 有足够工作量摊薄 launch 开销，又不至于把单步推入算力受限区。</p>\n<p>失效条件可以按“越过临界点”的三种方式分类。其一是 chunk 标定过大：$c_{\\text{chunk}}$ 压过 $B_{\\text{decode}}$ 后，单步算力项主导，长预填请求虽然被切块，但每个调度步都在周期性击穿 TPOT 的 SLO，表现为延迟曲线上的锯齿而非平滑。其二是 chunk 过小：预填 kernel launch 开销占比升高，调度步数增多而每步有效 token 减少，$T_{\\text{step}}$ 中的固定开销（launch、同步、路由元数据准备）不再被摊薄，GPU 利用率与 TTFT 同时恶化——注意 TTFT 恶化是反直觉的，因为切得更细并不等于预填更快完成，步数膨胀吃掉了收益。其三是 MoE 路由偏斜：预填 token 与 decode token 的语义分布天然不同，混批后路由按 token 独立计算，两股分布的叠加会让热点专家容量溢出概率上升，触发 token 丢弃或排队，混合 dispatch 的负载不均进一步放大专家并行通信开销。这一条不受 chunk 大小单调控制，是方案的结构性上限。</p>\n<table class=\"mini\"><thead><tr><th>失效模式</th><th>主导项</th><th>系统代价落点</th><th>可观测信号</th></tr></thead><tbody><tr><td>chunk 过大</td><td>算力项分子抬升</td><td>TPOT 周期性击穿 SLO</td><td>TPOT 锯齿、算力利用率饱和</td></tr><tr><td>chunk 过小</td><td>固定开销占比</td><td>TTFT 与利用率双降</td><td>步数上升、每步有效 token 下降</td></tr><tr><td>路由偏斜</td><td>专家容量</td><td>丢弃/排队、EP 通信放大</td><td>热点专家队列深度、dispatch 不均衡</td></tr></tbody></table>\n<p>落到可实现层面，调度器需要每步做一次“是否注入 chunk”的判定，而不是无条件 piggyback。伪代码思路：先按 $\\text{TPOT}_{\\text{target}}$ 反解本步允许的 $T_{\\text{step}}$ 上限，估算当前 $B_{\\text{decode}}$ 下的带宽项耗时，若剩余预算足以容纳 $c_{\\text{chunk}}$ 的算力项则注入，否则跳过本步、让预填队列等待下一个窗口；同时维护一个按专家统计的容量水位，当预测到混批会推高热点专家占用时，缩小 chunk 或临时改为纯 decode 步。输出按来源拆分是必须的工程细节：预填 token 走因果 mask、decode token 走 KV gather，两条路径的 logits 与 KV 写入必须分通道处理，否则 mask 混淆会直接产生错误结果。chunk 完成后 KV 以 page 为单位写入，供后续 decode gather，这一步的写带宽与 decode 的读带宽在同一 HBM 上竞争，是混批之外另一处容易被忽略的代价。最终判断是：chunk size 不是性能旋钮而是 SLO 标定参数，其可标定区间由 $c^\\*_{\\text{chunk}}$ 与专家容量水位共同夹逼，工程上应把它当作随负载配方漂移的量定期重标，而不是一次设定后固定不变。</p>\n\n<h3 id=\"alg-chunked-prefill-sec-20\">二十 · chunk 标定的失效边界：从 $T_{\\text{step}}$ 的两项看干扰上限</h3>\n<p>混批的代价不是均匀分摊的，而是由 $T_{\\text{step}}$ 中两项的相对大小决定谁主导。设 $B_{\\text{step}} = B_{\\text{decode}} + c_{\\text{chunk}}$，则单步时间近似为 $\\max\\left(\\frac{B_{\\text{dec}}N_{\\text{kv}}}{\\text{BW}},\\ \\frac{B_{\\text{dec}}+c_{\\text{chunk}}}{\\text{FLOPs}_{\\text{peak}}}\\right)$。关键一步在于：decode 项只随 $B_{\\text{dec}}$ 线性增长而与 $c_{\\text{chunk}}$ 无关，预填项却随 $c_{\\text{chunk}}$ 线性增长。当 $c_{\\text{chunk}}$ 增大到使第二项越过第一项时，单步从带宽受限翻转为算力受限，预填 chunk 开始直接抬高 TPOT——这就是“chunk 过大拖慢 decode”的定量含义。反过来，$c_{\\text{chunk}}$ 过小时第二项远低于第一项，单步仍由 decode 的 KV 带宽决定，预填几乎是“搭便车”，但每步有效 token 减少、调度步数增多，kernel launch 与调度开销占比上升，TTFT 反而恶化。可用下表判断当前落在哪一侧：</p>\n<table class=\"mini\"><thead><tr><th>区间</th><th>主导项</th><th>TPOT 影响</th><th>TTFT 影响</th><th>主要风险</th></tr></thead><tbody><tr><td>$c_{\\text{chunk}}$ 偏小</td><td>KV 带宽项</td><td>几乎不变</td><td>步数增多、launch 开销占比高而变差</td><td>利用率下降</td></tr><tr><td>临界附近</td><td>两项相当</td><td>抖动最小</td><td>随 $c_{\\text{chunk}}$ 线性改善</td><td>需按 SLO 精标</td></tr><tr><td>$c_{\\text{chunk}}$ 偏大</td><td>算力项</td><td>被预填算力拖慢、周期性击穿 SLO</td><td>改善但长预填仍周期性独占</td><td>decode 饿死复发</td></tr></tbody></table>\n<p>伪代码落到可实现层面，调度器每步只需三件事：取全部 decode token、取一个预填 chunk、按来源打标。</p>\n<div class=\"formula\">$$\\begin{aligned}\n&amp;\\textbf{while } Q_{\\text{pre}} \\neq \\varnothing \\textbf{ or } Q_{\\text{dec}} \\neq \\varnothing:\\\\\n&amp;\\quad \\text{batch} \\leftarrow \\text{gather}(Q_{\\text{dec}}) \\parallel \\text{pop\\_chunk}(Q_{\\text{pre}}, c_{\\text{chunk}})\\\\\n&amp;\\quad \\text{src} \\leftarrow [\\text{DEC}]^{B_{\\text{dec}}} \\parallel [\\text{PRE}]^{c_{\\text{chunk}}}\\\\\n&amp;\\quad y \\leftarrow \\text{forward}(\\text{batch},\\, \\text{mask}=\\text{causal if PRE else kv\\_gather})\\\\\n&amp;\\quad \\text{write\\_page}(y[\\text{PRE}].kv);\\ \\text{emit}(y[\\text{DEC}]);\\ \\text{requeue\\_rest}(Q_{\\text{pre}})\n\\end{aligned}$$</div>\n<p>实现上的硬约束是 mask 与输出必须按 src 拆分，否则因果 mask 与 KV gather 混用会污染 decode 的注意力结果；MoE 层路由按 token 独立计算，预填与 decode 混合 dispatch 后路由分布比纯 decode 更偏斜，热点专家容量溢出会触发丢弃或排队，并把专家并行的通信开销放大——这是该方案真正的规模上限，而非 chunk 大小本身。因此标定顺序应是先按 SLO 定 $c_{\\text{chunk}}$ 的临界值，再检查热点专家的容量余量是否撑得住混批后的偏斜分布；若撑不住，缩小 $c_{\\text{chunk}}$ 只会把问题从算力项转移到 launch 开销，需从专家容量侧解决。</p>\n<h3 id=\"alg-chunked-prefill-sec-21\">二十一 · 请求形态：什么样的负载才吃这套配方</h3>\n<p>分块预填与解码 piggyback 的负载前提是“长预填与在线 decode 同时在场”。只有当系统里持续存在两类请求——一类是动辄数千 token 的提示、需要一次吃掉大量算力；另一类是已经进入自回归、每步只吐一个 token 的会话——把预填切块塞进 decode 批次才有意义。若负载是纯离线批量打分，全部请求都是预填、没有 decode 在跑，chunk 化只是把一次大前向拆成多次小前向，白白增加 kernel launch 与调度开销；若负载是纯短对话，提示只有几十个 token，预填本身就只占一步，切块反而制造额外调度步。真正的甜区是“长提示 + 长会话”的混合流量：提示长度分布右偏、decode 会话数稳定在几十到几百、且 TTFT 与 TPOT 被同一个 SLO 同时约束。</p>\n<p>长度分布的形状直接决定 chunk 的收益。设提示长度服从重尾分布，少量超长请求贡献了大部分预填 token；这些请求正是独占 GPU、把 decode 饿死的元凶。把它们的预填切成固定块后，每个调度步注入的预填量被钉死，长请求对 decode 的干扰从“一次性巨浪”变成“恒定小流量”。反之，若长度分布集中在短区间，切块带来的调度次数上升会盖过收益。工程判断很直接：先统计线上提示长度的分位数，若 P99 远大于 P50，且 decode 并发不为零，这套配方成立；若 P99 与 P50 同量级，整段预填更划算。</p>\n<p>并发与批大小的配方是 $$B_{\\text{step}} = B_{\\text{decode}} + c_{\\text{chunk}}$$，其中 $B_{\\text{decode}}$ 是当前所有 decode 请求本步要算的 token 数（近似等于活跃会话数），$c_{\\text{chunk}}$ 是每步注入的预填 chunk 大小，材料给出的示例是 512 token。这个式子说明批大小不是自由参数：decode 并发涨，$B_{\\text{decode}}$ 涨，若 $c_{\\text{chunk}}$ 不变，预填在总批次中的占比下降，TTFT 被拉长；decode 并发跌，预填占比上升，TPOT 受冲击。所以并发规模必须与 chunk 大小联动标定，而不是各自独立调。</p>\n<p>具体例子：一个在线服务，活跃会话约数百、提示长度 P50 在千级、P99 在万级。若按整段预填调度，一条万级提示会连续占用多个步的算力，期间所有 decode 会话的 TPOT 被拉出尖峰；改成每步注入 512 token 的 chunk 后，该长请求被摊到约二十个调度步，每步对 decode 的额外算力负担被限定在一个 chunk 的量级，TPOT 尖峰被削平，代价是这条请求的 TTFT 被拉长到二十步。这就是配方本质：用 TTFT 换 TPOT 的稳定性，而交换比例由 chunk 大小决定。</p>\n\n<h3 id=\"alg-chunked-prefill-sec-22\">二十二 · 批内配比：decode 与预填的算力/带宽账</h3>\n<p>混批的代价必须用公式算清楚。单步时间近似为 $$T_{\\text{step}}\\approx\\max\\left(\\frac{B_{\\text{dec}}N_{\\text{kv}}}{\\text{BW}},\\ \\frac{B_{\\text{dec}}+C_{\\text{chunk}}}{\\text{FLOPs}_{\\text{peak}}}\\right)$$，前一项是 decode 侧读 KV 的带宽下界，后一项是整批 token 过权重与计算的算力下界。decode token 每步都要把历史 KV 全读一遍，是带宽密集；预填 token 一次前向算完整个 chunk，是算力密集。混批时这两项同时进入 max，谁大谁定步长。当 $B_{\\text{dec}}N_{\\text{kv}}/\\text{BW}$ 占主导，说明批次被 decode 的 KV 读取拖住，此时塞进 chunk 几乎不增加步长，预填是“免费搭车”；当 $(B_{\\text{dec}}+C_{\\text{chunk}})/\\text{FLOPs}_{\\text{peak}}$ 占主导，说明算力已饱和，chunk 每加一个 token 都直接推高步长，decode 的 TPOT 被等比拖慢。</p>\n<p>由此得到配比判据：chunk 大小的上限应使算力项不超过带宽项，即 $C_{\\text{chunk}} \\lesssim B_{\\text{dec}}N_{\\text{kv}}\\cdot\\text{FLOPs}_{\\text{peak}}/\\text{BW} - B_{\\text{dec}}$。工程上不必解这个不等式，只需在标定时观察 $T_{\\text{step}}$ 随 $C_{\\text{chunk}}$ 的增长曲线：在拐点之前加 chunk 不涨步长，拐点之后线性上涨。512 token 之所以常被当作起点，是因为在中等 decode 并发下它通常落在拐点附近；并发越高，可承受的 chunk 越大，并发越低，chunk 必须收小。</p>\n<p>TPOT 的约束写成 $$\\text{TPOT}\\le \\frac{T_{\\text{step}}}{\\text{tokens/step}}$$，其中 tokens/step 对每个 decode 请求而言是 1。这意味着 TPOT 直接等于步长，任何让 $T_{\\text{step}}$ 上涨的配比都会原样反映到用户感知的 token 间隔上。于是“decode 批次 + 一个 chunk”的设计有一个隐含前提：decode 侧的带宽项必须足够大，才能吸收 chunk 的算力增量。若 decode 并发很低、KV 读取量很小，带宽项撑不起场面，chunk 的算力增量立刻变成 TPOT 抖动——这正是低并发下这套配方失灵的原因。</p>\n<p>具体例子：decode 并发为个位数时，$B_{\\text{dec}}N_{\\text{kv}}$ 很小，步长由算力项主导，此时注入 512 token 的 chunk 会让步长明显上涨，decode 用户感到卡顿；把 chunk 降到几十 token，步长回落，但预填 kernel 的固定开销占比升高，TTFT 反而变差。这说明配比不是单调优化，而是存在一个由并发决定的窄窗口。</p>\n\n<h3 id=\"alg-chunked-prefill-sec-23\">二十三 · 负载不对：三种典型失衡</h3>\n<p>第一种失衡是 chunk 过大压过 decode 批次。当 $c_{\\text{chunk}}$ 显著大于 $B_{\\text{decode}}$，算力项被预填主导，每个调度步的步长由 chunk 决定，decode 的 TPOT 被预填算力拖慢。长预填请求虽然被切块，但每块都足够大，仍会周期性击穿延迟 SLO——切块只是把一次长阻塞换成多次中等阻塞，没有真正削平尖峰。这种形态在提示极长、decode 并发偏低的场景最常见，表现为 TPOT 呈周期性锯齿，周期等于 chunk 数。</p>\n<p>第二种失衡是 chunk 过小。预填 kernel launch 开销在每步中占比升高，调度步数增多而每步有效 token 减少，GPU 利用率与 TTFT 同时恶化。切块本是为了让预填与 decode 共享一次权重读取，但块小到一定程度，权重读取的固定成本摊不薄，piggyback 的带宽收益消失，只剩下调度开销。表现为 TTFT 随 chunk 减小而变长，且 GPU 空闲周期增多。</p>\n<p>第三种失衡是混批导致 MoE 路由分布偏斜。预填 token 与 decode token 的语义分布不同——预填是整段提示的混合内容，decode 是当前生成位置的局部上下文——混在一个批次里做路由，专家命中分布比单一来源更偏斜，热点专家容量溢出概率上升，触发 token 丢弃或排队，混合 dispatch 的负载不均又放大专家并行通信开销。这是这套配方特有的失败模式：它靠共享前向摊薄专家权重带宽，却也把两类 token 的路由分布搅在一起。容量因子路由与令牌丢弃那条线讲的正是溢出后的处置，此处只需记住：混批让溢出更容易发生。</p>\n<p>具体例子：一个 MoE 模型服务，decode 并发中等、提示长度重尾。chunk 设为 512 时 TPOT 平稳；某次流量低谷 decode 并发骤降，同样的 512 chunk 立刻让 TPOT 出现锯齿，因为算力项被预填主导。运维若只看平均 TPOT 不会发现，必须看分位尾部的抖动。这说明 chunk 必须随并发自适应，固定值在负载漂移下必然失衡。</p>\n\n<h3 id=\"alg-chunked-prefill-sec-24\">二十四 · 标定方法：按 SLO 反解 chunk</h3>\n<p>标定的目标是同时满足 TTFT 与 TPOT 两个约束，而这两个约束对 chunk 的要求方向相反：chunk 大则 TTFT 好（预填推进快）、TPOT 差；chunk 小则 TPOT 好、TTFT 差。可行域是两者的交集。做法是固定 decode 并发档位，扫描 chunk 大小，测每档的 $T_{\\text{step}}$ 与预填吞吐，画出两条约束线，取交点附近的 chunk 作为该并发档的标定值。由于材料未给出具体 SLO 数值与批大小，标定必须以线上真实流量为准，不能照搬 512 这个示例。</p>\n<p>更稳的做法是把 chunk 做成并发度的函数而非常数：当 $B_{\\text{decode}}$ 高，带宽项有余量，放大 chunk 加速预填；当 $B_{\\text{decode}}$ 低，收紧 chunk 保护 TPOT。伪代码思路是每步调度前估算两项下界，若算力项已接近带宽项则本步不注入 chunk 或注入更小的 chunk，否则注入标称 chunk。这把“按 SLO 精细标定”从离线一次性工作变成在线闭环，代价是需要每步做一次轻量估算，且估算误差会带来 chunk 抖动，需加平滑。</p>\n<p>代价落在调度器上：每步多一次配比决策，调度路径变长；chunk 动态变化使预填请求的完成时间不再可预测，TTFT 的方差上升。工程判断是——若流量平稳，固定 chunk 加定期复核足够；若流量有明显波峰波谷，动态 chunk 的收益盖过调度开销。具体例子：白天高并发用大 chunk 抢 TTFT，夜间低并发自动收小 chunk 保 TPOT，同一套代码覆盖两种形态，而不必切换部署模式。</p>\n\n<h3 id=\"alg-chunked-prefill-sec-25\">二十五 · 与分离部署的负载分界</h3>\n<p>这套配方不拆 GPU 池，预填与解码共享同一前向与同一份专家权重，靠 chunk 大小而非资源隔离控制干扰。因此它的负载适用面有一个明确上界：decode 并发必须足够高，使带宽项能吸收 chunk 的算力增量；预填流量必须足够连续，使每个调度步都有 chunk 可注入。若 decode 并发长期偏低，带宽项撑不住，chunk 只能收到很小，piggyback 的摊薄收益消失，此时预填解码分离部署更合适——用独立资源池隔离两类负载，代价是专家权重存两份、跨池传输 KV。分界线就是“共享一份权重摊薄带宽”与“资源隔离换确定性”之间的取舍，而这条线由并发规模画出。</p>\n<p>规模上限则来自热点专家容量。混批使路由偏斜，专家并行下热点专家的排队与通信开销随 batch 增大而放大，chunk 再大也压不住这条上限。因此这套配方的容量规划不能只看 GPU 算力与带宽，还要看专家容量的余量：当 decode 并发与 chunk 同时推高，专家溢出的概率上升，有效吞吐反而下降。具体例子：扩容时若只加 GPU 不改 chunk 与容量因子，混批批次变大、路由更偏斜，热点专家先饱和，扩容收益被吃掉——这说明负载配方必须与专家容量一起标定，单看 token 吞吐会误判。</p>\n\n<h3 id=\"alg-chunked-prefill-sec-26\">二十六 · 负载配方：长预填与在线解码的混合比例决定成败</h3>\n<p>这套方案不是通用加速器，它只在“长预填请求与在线 decode 请求同时存在”的混合负载下才成立。调度关系为 <span class=\"formula\">$$B_{\\text{step}} = B_{\\text{decode}} + c_{\\text{chunk}}$$</span>，其中 $B_{\\text{decode}}$ 是当前 decode 批次 token 数、$c_{\\text{chunk}}$ 是每步注入的预填 chunk 大小（材料示例为 512 token）。负载配方的本质是让 $B_{\\text{decode}}$ 与 $c_{\\text{chunk}}$ 处在同一量级：若 decode 批次远大于 chunk，预填只是搭车，干扰可控；若 chunk 压过 decode 批次，piggyback 就变成预填主导，decode 沦为陪跑。因此适用形态是“持续有 decode 流量、同时有长预填排队”的在线服务，而非纯离线批量预填或纯 decode 的短请求流。</p>\n<p>长度分布直接决定 chunk 标定的可行区间。请求预填长度若普遍接近或小于 chunk size，切块收益趋近于零，反而增加调度步数与 kernel launch 次数；只有当预填长度显著超过 chunk（长文档、长上下文、RAG 拼接、多轮历史）时，切块才能把单次长预填的独占窗口打散成可预测的小片。并发侧则要求 decode 侧有足够多的活跃请求来“托住”每个调度步的有效 token 数——decode 并发过低时，$B_{\\text{decode}}$ 太小，混批批次的有效算力被 chunk 的固定开销稀释，GPU 利用率与 TTFT 同时恶化。可用下表判断负载是否落在配方内：</p>\n<table class=\"mini\"><thead><tr><th>负载特征</th><th>落在配方内</th><th>落在配方外</th></tr></thead><tbody><tr><td>预填长度 vs chunk</td><td>远大于 512 token，可切多块</td><td>接近或小于 chunk，切块无收益</td></tr><tr><td>decode 并发</td><td>持续有活跃 decode 批次</td><td>decode 稀疏，批次被 chunk 主导</td></tr><tr><td>路由分布</td><td>混合 dispatch 后专家负载可摊薄</td><td>偏斜放大，热点专家溢出</td></tr></tbody></table>\n<p>负载不对时的失效是双向的。chunk 标定过大，单步预填 token 数压过 decode 批次，decode 的 TPOT 被预填算力周期性拖慢，长预填请求仍会击穿延迟 SLO；chunk 过小，预填 kernel launch 开销占比升高，调度步数增多而每步有效 token 减少，TTFT 与利用率一起变差。更隐蔽的代价在 MoE 层：预填 token 与 decode token 混批后路由按 token 独立计算，两类 token 的专家分布叠加使路由更偏斜，热点专家容量溢出触发 token 丢弃或排队，混合 dispatch 的负载不均进一步放大专家并行通信开销。这正是该方案不拆分 GPU 池、靠 chunk 大小而非资源隔离控制干扰所付出的结构性代价——热点专家容量成为它的规模上限。</p>\n<h3 id=\"alg-chunked-prefill-sec-27\">二十七 · 硬件档位与并行拓扑的耦合选择</h3>\n<p>分块预填与解码 piggyback 的部署配方里，第一个决策不是 chunk size，而是硬件档位与并行拓扑的组合。这套算法不拆分 GPU 池，预填 chunk 与 decode token 共享同一份专家权重、同一次前向，因此并行拓扑必须同时满足两类负载的约束：decode 侧要求低 TPOT，预填侧要求高算力吞吐。在 Blackwell 上，单机内以 NVLink 5 连接的 8 卡 NVL 域是基本单元，跨机由 GB200/GB300 NVL72 的机柜级 NVLink 域扩展。拓扑选择的核心判据是专家并行（EP）的 all-to-all 是否落在 NVLink 域内——一旦混批的 MoE dispatch 跨出 NVLink 域，专家并行通信开销会直接吃掉 piggyback 摊薄权重带宽带来的收益。</p>\n<p>具体机制上，piggyback 每步的批次是 $B_{\\text{step}} = B_{\\text{decode}} + c_{\\text{chunk}}$，MoE 层对这批 token 按 token 独立路由，预填 token 与 decode token 混合 dispatch。若采用 EP，dispatch 的 token 数等于 $B_{\\text{step}}$ 乘以每 token 命中的专家数，通信量与 $B_{\\text{step}}$ 成正比。预填 chunk 注入使 $B_{\\text{step}}$ 在调度步之间波动，all-to-all 的负载均衡难度高于纯 decode 稳态。因此拓扑上优先让 EP 组落在单机 8 卡 NVLink 域内，把跨机通信留给张量并行（TP）或流水线（PP）这类通信模式固定的维度，避免让随 chunk 波动的 EP 通信跨越机柜边界。</p>\n<p>代价上，硬件档位直接决定 $T_{\\text{step}}$ 公式中两项的相对大小：</p>\n<div class=\"formula\">$$T_{\\text{step}}\\approx\\max\\left(\\frac{B_{\\text{dec}}N_{\\text{kv}}}{\\text{BW}},\\ \\frac{B_{\\text{dec}}+C_{\\text{chunk}}}{\\text{FLOPs}_{\\text{peak}}}\\right),\\quad \\text{TPOT}\\le \\frac{T_{\\text{step}}}{\\text{tokens/step}}$$</div>\n<p>在 B200/B300 这一档，HBM 带宽与 FP4/FP8 峰值算力都高，decode 侧带宽项与预填侧算力项的交叉点向更大的 $C_{\\text{chunk}}$ 移动，意味着同一 SLO 下可以选更大的 chunk。在 GB200/GB300 NVL72 机柜档，单卡算力相同但域内卡数多，EP 组可以更大、专家权重摊得更薄，代价是 all-to-all 跳数增加。工程判断是：单机 8 卡档适合中小 MoE 与高 TPOT 敏感场景，机柜档适合专家数多、需要大 EP 组摊薄权重带宽的场景，但必须把混批 dispatch 限制在 NVLink 域内。</p>\n<p>具体例子：一个专家数较多、单卡放不下全部专家权重的 MoE 模型，若把 EP 组设为 8 卡单机，每步混批的 dispatch 全在 NVLink 5 域内完成；若把 EP 组扩到跨机 16 卡，虽然专家权重带宽摊得更薄，但每个调度步的 all-to-all 跨越机柜链路，chunk 注入带来的批次波动会放大跨机通信的排队抖动，TPOT 的尾部延迟反而变差。此时应退回单机 EP 组，用更大的 chunk 换取预填吞吐。</p>\n\n<h3 id=\"alg-chunked-prefill-sec-28\">二十八 · 量化方案的搭配与数值边界</h3>\n<p>piggyback 的量化方案要同时服务两类 token：decode token 是带宽受限的，权重读取占主导；预填 chunk 是算力受限的，矩阵乘的 FLOPs 占主导。Blackwell 的 NVFP4 与 FP8 在 tcgen05 路径上都有对应的 MMA 形态，量化选择的原则是让权重格式在两类 token 下都不触发反量化瓶颈。权重用 NVFP4 微缩放格式存放，decode 侧每步读取的权重量减半，直接压低 $T_{\\text{step}}$ 的带宽项；预填侧则依赖 tcgen05 的 FP4 MMA 吞吐，把算力项压住。激活侧的选择更敏感：预填 chunk 的激活分布随 chunk 内容变化，若激活量化粒度过粗，预填 token 的数值误差会通过 KV 写入 page 污染后续 decode 的 attention。</p>\n<p>机制上，MoE 层的路由按 token 独立计算，预填 token 与 decode token 混合 dispatch 后进入同一组专家权重。若权重是 NVFP4、激活是 FP8，专家 GEMM 需要在 MMA 前做格式对齐；若权重与激活都用 NVFP4，则 tcgen05 可以直接吃 FP4 操作数，融合度更高。工程上倾向权重 NVFP4、激活 FP8 的组合：decode 侧权重带宽收益最大，预填侧激活精度留有余量，KV 写入 page 的数值稳定性更好。代价是混合精度 GEMM 在部分专家上需要额外的格式转换，这部分开销在 chunk 较小时占比上升。</p>\n<p>显存代价要算清楚：权重 NVFP4 使专家权重显存约为 FP16 的四分之一，腾出的空间可以加大分页 KV 的 page 池，直接缓解混批下 KV gather 的显存压力。但预填 chunk 完成后 KV 写入 page 时，若 KV 也做量化，page 内的 KV 精度与 decode 侧 gather 的精度必须一致，否则同一请求的预填段与解码段数值不一致，attention 输出会出现分段偏差。因此 KV 量化策略要与权重量化解耦决策：权重激进量化换带宽，KV 保守量化保一致性。</p>\n<p>具体例子：一个 MoE 模型在 B200 上部署，专家权重用 NVFP4 存放，激活用 FP8，KV 保持 BF16 写入 page。预填 chunk 的 512 token 过专家 GEMM 时走 FP4 权重乘 FP8 激活的混合路径，decode token 在同一批次里共享同一次权重读取，权重带宽被两类 token 共同摊薄；KV 写入 page 用 BF16，后续 decode 的 KV gather 不引入额外反量化。若把 KV 也压到 FP8，page 池变大、可容纳更多并发请求，但预填段与解码段的 KV 精度差异需要在 attention 里做补偿，复杂度上升。</p>\n\n<h3 id=\"alg-chunked-prefill-sec-29\">二十九 · KV 策略与 page 池的容量标定</h3>\n<p>piggyback 的 KV 策略有一个与其他调度算法不同的约束：预填 chunk 是分段完成的，每个 chunk 完成后才把 KV 写入 page，因此 page 的分配时机与 chunk 边界绑定。调度器每步取出一个预填 chunk，该 chunk 的 KV 在该步结束时写入 page，供后续 decode 的 KV gather 使用。这意味着 page 池的容量必须覆盖“已写入的预填段 + 正在解码的段 + 未来 chunk 的预留”，而不是整段预填一次性占满。</p>\n<p>机制上，分页 KV 以 page 为单位管理，预填 chunk 的 token 按 page 粒度落盘。chunk size 为 512 token 时，若 page 大小为固定 token 数，一个 chunk 跨越若干 page，写入是批量的、对齐的。decode token 的 KV gather 按 page 索引读取，预填段与解码段在 page 表里是连续的逻辑地址，物理 page 可以不连续。这种布局让预填 chunk 的写入与 decode 的读取共享同一套 page 表，避免了整段预填独占连续显存的问题。</p>\n<p>容量标定的公式思路是：page 池所需容量等于并发请求数乘以每请求的平均上下文长度乘以每 token 的 KV 字节数，再乘以一个安全系数。混批下并发请求数由 decode 批次决定，预填队列的请求也在消耗 page 预留。chunk 越小，预填请求在 page 池里停留的时间越长（因为分段写入、分段占页），page 周转率下降；chunk 越大，单步写入的 page 数越多，写入带宽峰值越高。工程上按 SLO 的 TTFT 上限反推预填队列深度，再按队列深度乘以每请求预留 page 数确定池容量。</p>\n<p>代价上，page 池不足会触发请求排队，直接恶化 TTFT；page 池过大则挤占专家权重显存，迫使权重换出或降低 EP 组规模。具体例子：并发 decode 请求较多、上下文较长的场景，若 page 池按整段预填一次性预留，显存很快耗尽；改为按 chunk 分段预留后，同一显存可以支撑更多并发请求，代价是 page 表的碎片化管理开销上升，需要更细的 page 回收策略。预填 chunk 完成后 KV 写入 page 的动作与 decode 的 KV gather 在同一调度步内交错，写入与读取的显存带宽竞争需要在 page 布局上做隔离。</p>\n\n<h3 id=\"alg-chunked-prefill-sec-30\">三十 · 调度参数的标定顺序</h3>\n<p>调度参数不是一个一个独立调的，piggyback 的参数之间有明确的依赖顺序：先定 chunk size，再定 decode 批次上限，最后定预填队列深度与调度步的准入策略。chunk size 决定预填对 decode 的干扰上限，是这套算法唯一直接控制干扰的旋钮；decode 批次上限决定每步的 $B_{\\text{decode}}$，进而决定 $B_{\\text{step}}$ 的基线；预填队列深度决定 TTFT 的上界。</p>\n<p>标定方法上，先用 $T_{\\text{step}}$ 公式估算给定硬件档位下 decode 侧的带宽项与预填侧的算力项，找出两者相等时的 $C_{\\text{chunk}}$ 临界值。chunk 超过这个临界值，预填算力项开始主导 $T_{\\text{step}}$，decode 的 TPOT 被预填拖慢；chunk 低于临界值，预填 kernel launch 开销占比上升，调度步数增多而每步有效 token 减少。临界值附近是标定的起点，再按 SLO 的 TPOT 上限向下微调，留出混批路由偏斜的余量。</p>\n<p>失败模式的量化描述：chunk size 标定过大使单步预填 token 数压过 decode 批次，$B_{\\text{step}}$ 中预填占比过高，decode 的 TPOT 被预填算力拖慢，长预填请求仍会周期性击穿延迟 SLO；chunk size 过小使预填 kernel launch 开销占比升高，调度步数增多而每步有效 token 减少，GPU 利用率与 TTFT 同时恶化。这两个方向的失败模式在参数空间上夹出一个可行区间，标定的任务就是在这个区间内找满足双 SLO 的点。</p>\n<p>具体例子：材料给出的 chunk size 示例是 512 token，这是一个起点而非定值。在 decode 批次较大、TPOT 敏感的部署里，512 可能偏大，需要降到更小的 chunk 以减少单步预填对 decode 的挤压；在预填队列积压、TTFT 敏感而 TPOT 有余量的部署里，512 可能偏小，需要加大 chunk 提升预填吞吐。调度步的准入策略还要处理预填队列为空的情况：此时 $B_{\\text{step}} = B_{\\text{decode}}$，退化为纯 decode 批次，chunk 参数不生效，调度器应把空闲的算力留给 decode 的更大批次或投机解码的验证步。</p>\n\n<h3 id=\"alg-chunked-prefill-sec-31\">三十一 · 可复现的配置思路与稳定性校验</h3>\n<p>把上述决策串成一条可复现的配置路径：第一步选硬件档位与 EP 组，判据是混批 dispatch 是否落在 NVLink 域内，落在域内则 EP 组可以放大，落在域外则退回单机 EP 组；第二步定量化方案，权重 NVFP4、激活 FP8、KV 保守量化，权重带宽收益与 KV 一致性分开决策；第三步定 KV page 池容量，按 chunk 分段预留而非整段预留，池容量由预填队列深度与并发 decode 数共同决定；第四步按 $T_{\\text{step}}$ 临界值标定 chunk size，再按双 SLO 微调；第五步定 decode 批次上限与预填队列深度，用准入策略处理预填队列空与非空两种稳态。</p>\n<p>稳定性校验要盯三个指标：混批的 MoE 路由偏斜度、热点专家的容量溢出率、预填 kernel launch 开销占比。路由偏斜度上升意味着预填 token 与 decode token 的专家命中分布差异大，热点专家容量溢出会触发 token 丢弃或排队，混合 dispatch 的负载不均放大专家并行通信开销。校验方法是按来源拆分输出，分别统计预填 token 与 decode token 的专家命中直方图，若两者分布差异超过阈值，说明 chunk 内容与 decode 负载的专家偏好冲突，需要调整 chunk size 或调度步的预填注入比例。</p>\n<p>按来源拆分输出还有一个稳定性作用：attention 对预填 token 用因果 mask、对 decode token 用 KV gather，两者的 mask 语义不同，混批后若不在输出处按来源拆分，mask 混淆会导致预填段的 attention 结果污染 decode 段。拆分动作本身有代价——额外的索引与拷贝，但在 chunk 较大时占比可忽略，chunk 较小时成为固定开销的一部分，这也是 chunk 不能过小的另一个原因。</p>\n<p>具体例子：一个长预填与在线 decode 混合的在线服务，按上述路径配置后，预填队列非空时每步注入 512 token 的 chunk 与 decode 批次拼批，预填 chunk 完成后 KV 写入 page；预填队列为空时退化为纯 decode。运行中若发现 TPOT 尾部抖动，先查路由偏斜度，再查 chunk 是否超过 $T_{\\text{step}}$ 临界值；若发现 TTFT 恶化，先查预填队列深度与 page 池容量，再查 chunk 是否过小导致 launch 开销占比上升。这套校验顺序把失败模式与参数一一对应，避免在多个旋钮之间盲目试错。</p>\n\n<h3 id=\"alg-chunked-prefill-sec-32\">三十二 · 混批配方的失效边界：chunk 标定、专家热点与步进代价</h3>\n<p>这套配方的可复现性不在于给出固定数字，而在于把五个旋钮的标定顺序固定下来：先由 SLO 反推 chunk 上限，再由 MoE 专家容量反推混批 token 上限，最后才选并行拓扑与量化。核心约束是步进时间公式 <span class=\"formula\">$$T_{\\text{step}}\\approx\\max\\left(\\frac{B_{\\text{dec}}N_{\\text{kv}}}{\\text{BW}},\\ \\frac{B_{\\text{dec}}+C_{\\text{chunk}}}{\\text{FLOPs}_{\\text{peak}}}\\right),\\quad \\text{TPOT}\\le \\frac{T_{\\text{step}}}{\\text{tokens/step}}$$</span> 它说明混批后单步时间由两项中较大者决定：decode 侧受 KV 带宽支配，预填 chunk 侧受算力支配。当 <span class=\"formula\">$$B_{\\text{step}} = B_{\\text{decode}} + c_{\\text{chunk}}$$</span> 中的 $c_{\\text{chunk}}$ 使算力项超过带宽项时，预填就从“搭便车”变成“拖车”，decode 的 TPOT 被预填算力直接拉长。因此 chunk 上限应由 TPOT 预算反解，而不是由显存或队列长度决定；512 token 只是材料给出的示例量级，实际取值必须落在带宽项仍占优的区间内。</p>\n<p>失效条件有三类，且互相耦合。第一类是 chunk 过大：单步预填 token 数压过 decode 批次，长预填请求仍会周期性击穿延迟 SLO，表现为 TPOT 抖动而非平均值恶化——监控上要看 P99 而非均值。第二类是 chunk 过小：预填 kernel launch 开销占比升高，调度步数增多而每步有效 token 减少，GPU 利用率与 TTFT 同时恶化，此时增加并行度无用，因为瓶颈在调度器而非 SM。第三类是混批引起的 MoE 路由偏斜：预填 token 与 decode token 的语义分布不同，混合 dispatch 后热点专家容量溢出概率上升，触发 token 丢弃或排队，专家并行通信开销被负载不均放大。这一条是规模上限的真正来源——它不随 chunk 调小而消失，只随混批比例下降而缓解。</p>\n<table class=\"mini\"><thead><tr><th>旋钮</th><th>标定依据</th><th>越界后的系统代价</th></tr></thead><tbody><tr><td>chunk size</td><td>TPOT 预算反解，带宽项占优</td><td>过大拖慢 decode；过小 launch 开销吃掉利用率</td></tr><tr><td>混批比例</td><td>热点专家容量余量</td><td>专家溢出、token 排队、EP 通信放大</td></tr><tr><td>KV page 策略</td><td>预填 chunk 完成即写 page</td><td>page 碎片化抬高 gather 延迟</td></tr><tr><td>量化方案</td><td>与权重带宽摊薄目标一致</td><td>精度回退改变路由分布，加剧偏斜</td></tr></tbody></table>\n<p>工程判断落在边界识别上：这套配方不拆分 GPU 池，预填与解码共享同一前向与同一份专家权重，靠 chunk 大小而非资源隔离控制干扰，因此它适合 decode 批次稳定、专家负载可观测的在线服务，而不适合预填请求突发且长度方差极大的场景——后者应转向预填解码分离部署。KV 以 page 为单位在 chunk 完成后写入，意味着 page 分配粒度必须与 chunk 对齐，否则 gather 侧会出现跨 page 拼接的额外延迟。量化方案的选择也不是独立的：更激进的低精度会改变 MoE 路由的数值分布，把原本均衡的专家负载推向偏斜，等于用精度换带宽的同时又抬高了第三类失效的概率。</p>\n<h3 id=\"alg-chunked-prefill-sec-33\">三十三 · 单步时间账：带宽项与算力项谁在压顶</h3>\n<p>混批之后，每个调度步的耗时不再是纯 decode 的带宽受限曲线，也不是纯预填的算力受限曲线，而是两条曲线的上包络。给定公式里这一步写成两个候选量的取大：一项是 decode 侧 KV 读取量除以显存带宽，另一项是（decode token 数加 chunk token 数）除以峰值算力。这个取大的结构决定了工程上最该盯的不是平均值，而是哪一项在 SLO 约束下先顶到天花板。</p>\n<div class=\"formula\">$$T_{\\text{step}}\\approx\\max\\left(\\frac{B_{\\text{dec}}N_{\\text{kv}}}{\\text{BW}},\\ \\frac{B_{\\text{dec}}+C_{\\text{chunk}}}{\\text{FLOPs}_{\\text{peak}}}\\right),\\quad \\text{TPOT}\\le \\frac{T_{\\text{step}}}{\\text{tokens/step}}$$</div>\n<p>把 $B_{\\text{step}} = B_{\\text{decode}} + c_{\\text{chunk}}$ 代进第二项就能看出 chunk 的代价位置：chunk 直接抬高算力项的分子，却完全不进入带宽项的分子。这意味着 chunk 增大时，算力项线性上升而带宽项不动，两条曲线的交点就是混批从“带宽主导”翻转为“算力主导”的临界 chunk。工程判断很直接：在 decode 批次已经足够大、KV 读取量已经压满带宽的部署里，任何 chunk 都是纯加项，混批的收益只剩权重读取摊薄；而在 decode 批次很小、带宽项远低于算力项的场景，chunk 可以近乎免费地搭车。512 token 这个示例值之所以常见，是因为它落在多数中大批次的带宽主导区间之外、又不至于让算力项翻倍，但它不是普适常数，必须按实际 $B_{\\text{decode}}$ 与 $N_{\\text{kv}}$ 重算交点。</p>\n<p>单步时间账还要除以每步有效 token 数才能落到 TPOT。chunk 过小时，$c_{\\text{chunk}}$ 缩小但调度步数增多，每步有效 token 减少，$T_{\\text{step}}$ 里的固定开销（kernel launch、路由、dispatch 同步）占比升高，TPOT 的分子没降多少而分母被摊薄，净效果是吞吐与 TTFT 同时恶化。这就是失败模式里“chunk 过小则预填 kernel launch 开销占比高”的定量来源：固定开销不随 chunk 缩放，chunk 越小它越贵。</p>\n\n<h3 id=\"alg-chunked-prefill-sec-34\">三十四 · 显存与 KV page：写入时机决定峰值</h3>\n<p>混批不改变 KV 的总量，但改变 KV 的写入节奏与峰值形态。预填 chunk 完成后才把 KV 写入 page，这个“完成即写”的语义意味着一个长预填请求在切块期间，其已算完的 chunk 对应的 KV 已经占住 page，而未算完的部分尚未分配。相比整段预填一次性占满，分块把 KV 分配摊到多个调度步，瞬时峰值下降，但总占用不变，且 page 的碎片化程度上升——每个 chunk 的边界都可能落在 page 中间，需要跨 page 拼接。</p>\n<p>显存侧真正的压力来自混批把两类 token 的临时缓冲叠在同一个前向里。MoE 层的 dispatch 缓冲按 token 独立计算路由，预填 token 与 decode token 混合 dispatch，缓冲区大小按 $B_{\\text{step}}$ 而非 $B_{\\text{decode}}$ 分配，等于把预填的激活峰值塞进 decode 的常驻工作集旁边。在专家权重已经与分页 KV 共存显存的部署里（该主题另有专述），这部分激活增量往往是压垮显存的最后一根稻草，而不是 KV 本身。工程上应把 dispatch 缓冲按 $B_{\\text{decode}} + c_{\\text{chunk}}$ 预留并计入容量规划，而不是沿用纯 decode 的预算。</p>\n<p>另一个隐性代价是 page 写入与 decode gather 的并发。预填 chunk 写 page 与 decode token 从 page gather 在同一批次内发生，写操作占用的带宽与 gather 的读带宽争抢同一份 HBM 通道。虽然写量相对读量小，但在带宽项已经主导 $T_{\\text{step}}$ 的区间，任何额外写流量都直接折算成 TPOT 抖动。把 chunk 的 page 写入安排在 decode gather 之后的独立小步，或用异步写掩盖，是控制这一项抖动的手段。</p>\n\n<h3 id=\"alg-chunked-prefill-sec-35\">三十五 · 带宽摊薄的真实收益与它的上限</h3>\n<p>混批最被低估的收益是权重读取摊薄：预填与解码共享一次前向、同一份专家权重，MoE 专家权重的读取带宽被两类 token 共同分摊。纯 decode 步里，权重读取量固定而 token 数少，权重带宽占比高；纯预填步里，算力密集但权重读取同样固定。混批把两者并到一次读取，单位 token 的权重带宽成本下降，这是 GPU 利用率提升的物理来源。</p>\n<p>但摊薄有上限，上限由路由偏斜决定。预填 token 的分布与 decode token 的分布不同——预填是整段文本的统计，decode 是当前上下文的局部统计——混批后路由分布更偏斜，热点专家被两类 token 同时命中，其容量溢出概率上升。溢出触发 token 丢弃或排队，被丢弃的 token 要么重算要么降级，直接表现为 TPOT 尾部的尖峰。更麻烦的是，偏斜放大专家并行的 All-to-All 通信量：热点专家所在设备收到的 token 数超过均值，dispatch 阶段的通信从均衡的全互联退化为热点汇聚，通信时间不再随 token 数线性缩放。规模上去以后，这一项通常是最先崩的——不是算力不够，也不是带宽不够，而是热点专家的容量与它背后的通信拓扑先饱和。</p>\n<p>量化收益时要区分两种摊薄：权重带宽摊薄是确定的、随 chunk 增大而增强；激活与通信摊薄是不确定的、随偏斜增大而减弱。前者可以用 $B_{\\text{step}}$ 直接估算，后者只能靠路由分布的在线统计判断。工程判断是：在专家数少、路由集中的模型上，混批的通信代价可能吃掉全部权重摊薄收益；在专家数多、路由分散的模型上，摊薄收益才站得住。</p>\n\n<h3 id=\"alg-chunked-prefill-sec-36\">三十六 · 通信与功耗：混批把两种密集叠在同一时钟周期</h3>\n<p>预填是算力密集，decode 是带宽密集，混批把两种密集叠在同一个前向的同一批 SM 上。这对通信的影响是双面的：一方面，两类 token 共享一次 All-to-All，通信次数从“预填一次加 decode 多次”降为每步一次，通信启动开销被摊薄；另一方面，单次 All-to-All 的负载更不均，热点专家的汇聚使单次通信的尾延迟拉长。通信的总量未必下降，但通信的次数下降，这对延迟敏感的解码路径有利，对带宽饱和的互联不利。</p>\n<p>功耗侧的角度常被忽略。算力密集的预填段把 SM 推到高利用率、高时钟，带宽密集的 decode 段 SM 利用率低但 HBM 满负荷。混批让同一批 SM 同时承担两种负载，功率在单步内更平稳，减少了纯预填步的功率尖峰与纯 decode 步的功率低谷之间的来回摆动。对 NVL72 这种整柜功率预算受限的部署，平稳的功率曲线意味着可以把更多 GPU 维持在接近功率上限的运行点，而不是为尖峰预留裕量。代价是单步功率上限更难压低，热设计点被抬高，机柜级散热必须按混批的持续功率而非纯 decode 的低功率来设计。</p>\n<p>尾延迟是混批最需要单独建模的一项。TPOT 的均值可以靠 chunk 标定得很好看，但尾部的尖峰来自三个源：热点专家溢出导致的排队、page 写入与 gather 的带宽争抢、以及长预填请求周期性到达时 chunk 队列的瞬时加深。第三个源最隐蔽：当多个长预填请求同时到达，预填队列深度上升，调度器每步仍只取一个 chunk，队列清空时间被拉长，TTFT 的尾部随之恶化。chunk 大小固定而队列可变，等于把 TTFT 的方差交给了到达过程。</p>\n\n<h3 id=\"alg-chunked-prefill-sec-37\">三十七 · 规模上去以后哪里先崩：三条饱和线的排序</h3>\n<p>把规模轴拉开，混批部署会依次撞上三条饱和线，顺序取决于模型形态而非硬件档位。第一条是热点专家容量线：路由偏斜随批量增大而放大，专家并行的 All-to-All 在热点汇聚处先饱和，表现为 TPOT 尾部尖峰与 token 丢弃率上升。第二条是显存线：dispatch 缓冲按 $B_{\\text{step}}$ 预留、KV page 碎片化、专家权重常驻，三者叠加把可用显存吃满，表现为可接纳的 decode 批次上限下降。第三条才是算力线：$T_{\\text{step}}$ 的算力项随 chunk 与 decode 批次之和上升，最终压过带宽项。</p>\n<table class=\"mini\"><thead><tr><th>饱和线</th><th>触发条件</th><th>可观测信号</th><th>缓解手段</th></tr></thead><tbody><tr><td>热点专家容量</td><td>混批路由偏斜放大，专家并行热点汇聚</td><td>TPOT 尾部尖峰、丢弃率上升</td><td>缩小 chunk、按来源拆分批次、限制混批比例</td></tr><tr><td>显存</td><td>dispatch 缓冲按 $B_{\\text{step}}$ 预留、page 碎片化</td><td>可接纳 decode 批次上限下降</td><td>按 chunk 上限预留缓冲、page 对齐切块</td></tr><tr><td>算力</td><td>$B_{\\text{decode}}+c_{\\text{chunk}}$ 压过带宽项</td><td>$T_{\\text{step}}$ 随 chunk 线性上升</td><td>按交点重算 chunk、decode 批次与 chunk 解耦调度</td></tr></tbody></table>\n<p>排序的工程含义是：扩容时不要先加算力，先看热点专家的通信与容量。混批把预填的算力密集灌进 decode 的带宽密集批次，最先被压垮的往往不是 FLOPs 而是专家并行的负载均衡。当热点专家容量成为规模上限时，继续增大 chunk 只会加深偏斜，正确动作是缩小 chunk、把预填 chunk 与 decode 批次按来源拆分调度，甚至退回部分资源隔离——这正是与预填解码分离部署的分界：混批靠 chunk 大小控制干扰，一旦 chunk 小到 kernel launch 开销不可接受、大到 decode 被拖慢，两端都不可行时，资源隔离重新变得划算。</p>\n<p>最后落到一个可操作的标定点：以 $T_{\\text{step}}$ 的两项交点为 chunk 上界，以 kernel launch 固定开销占比不超过单步时间某一比例为 chunk 下界，在这个区间内按 TPOT 尾部分位数而非均值选点。512 token 只是这个区间的一个样本，真正的判据是交点位置与固定开销占比，两者都随 $B_{\\text{decode}}$、$N_{\\text{kv}}$ 与专家并行拓扑变化，必须在线重标定而不是一次配死。</p>\n\n<h3 id=\"alg-chunked-prefill-sec-38\">三十八 · 混批步的系统代价：带宽、专家热点与尾延迟的先后崩点</h3>\n<p>把预填 chunk 与 decode 批次拼成统一步后，单步代价由两个瓶颈取大：KV 读取带宽项与算力项。前者随 decode 批次与 KV 长度线性增长，后者随 $B_{\\text{decode}}+c_{\\text{chunk}}$ 增长，而 $B_{\\text{step}} = B_{\\text{decode}} + c_{\\text{chunk}}$ 意味着 chunk 一旦压过 decode token 数，算力项就接管主导权，decode 的 TPOT 被预填的算力密集段直接拖长。这是该方案最先暴露的失效条件：chunk 标定过大时，长预填请求仍会周期性击穿延迟 SLO，只是把“饿死”换成了“周期性抖动”。</p>\n<div class=\"formula\">$$T_{\\text{step}}\\approx\\max\\left(\\frac{B_{\\text{dec}}N_{\\text{kv}}}{\\text{BW}},\\ \\frac{B_{\\text{dec}}+C_{\\text{chunk}}}{\\text{FLOPs}_{\\text{peak}}}\\right),\\quad \\text{TPOT}\\le \\frac{T_{\\text{step}}}{\\text{tokens/step}}$$</div>\n<p>规模上去后第二个崩点是专家容量。预填 token 与 decode token 的上下文分布差异明显，混批后 MoE 路由按 token 独立计算，混合 dispatch 使路由分布更偏斜，热点专家容量溢出概率上升；溢出触发 token 丢弃或排队，专家并行上的 all-to-all 通信量随不均衡放大，单步尾延迟由均值转向长尾。此时增大 chunk 会同时抬高算力项与偏斜度，减小 chunk 则调度步数增多、每步有效 token 减少，预填 kernel launch 开销占比升高，GPU 利用率与 TTFT 一起恶化——两端都不是可调的安全区，chunk size 只能按 SLO 精细标定，512 token 只是起点而非结论。</p>\n<table class=\"mini\"><thead><tr><th>规模变量</th><th>先崩的资源</th><th>可观测症状</th></tr></thead><tbody><tr><td>chunk 偏大</td><td>算力/尾延迟</td><td>TPOT 周期性尖峰，长预填击穿 SLO</td></tr><tr><td>chunk 偏小</td><td>launch 开销/调度</td><td>步数增多，TTFT 与利用率同降</td></tr><tr><td>decode 批次变长</td><td>KV 带宽</td><td>带宽项压过算力项，单步时间线性涨</td></tr><tr><td>专家并行度提高</td><td>专家热点/通信</td><td>all-to-all 不均衡，尾延迟拉长</td></tr></tbody></table>\n<p>工程判断落在两点：一是把 chunk 当作 SLO 标定参数而非固定常量，按 decode 批次实际 token 数与 KV 长度动态收放，使算力项不超过带宽项；二是对热点专家做容量预留或路由侧限流，避免混批偏斜把专家并行通信变成尾延迟主因。功耗层面，混批摊薄了专家权重读取，单位 token 的权重带宽开销下降，但算力项抬升使 SM 占用更满，能效改善只在 chunk 与 decode 比例合适时成立；比例失衡时省下的带宽被算力与通信吃回。</p>\n<h3 id=\"alg-chunked-prefill-sec-39\">三十九 · 精度漂移：混批下的数值一致性诊断</h3>\n<p>分块预填与解码 piggyback 的精度问题不来自算法本身，而来自“同一前向里两类 token 走不同数值路径”这一事实。预填 chunk 的 token 在 attention 里走因果 mask 分支，decode token 走 KV gather 分支；两者在 MoE 层混合 dispatch，路由按 token 独立计算，但共享同一份专家权重与同一套量化 scale。当预填 chunk 与 decode 批次拼成统一批次时，激活的动态范围由两类 token 共同决定——预填 token 的激活幅度通常更大，会拉高整批的 per-tensor 或 per-block 微缩放因子，decode token 的有效位宽被压缩。诊断这类漂移不能只看端到端困惑度，要在三个位置埋探针：MoE dispatch 前的激活直方图（按来源拆分统计）、专家 GEMM 输出的逐 token 相对误差（以 FP32 参考路径为基线）、KV 写入 page 前后的量化往返误差。判据是：把 decode token 单独成批跑一遍，与混批结果逐 token 比对，若相对误差在混批下系统性抬升而非随机分布，就是混批数值污染，而非权重量化本身的误差。工程上的回滚不是退回整段预填，而是给预填 chunk 与 decode 分别配置量化 scale 域（按来源分组做微缩放），代价是每组多一次 scale 归约、MoE 层多一次分组同步，单步延迟增加一个小的固定开销，但避免了整批 scale 被预填拉偏。</p>\n<div class=\"formula\">$$\\varepsilon_{\\text{mix}}=\\frac{1}{|\\mathcal{D}|}\\sum_{t\\in\\mathcal{D}}\\frac{\\lVert y_t^{\\text{mix}}-y_t^{\\text{ref}}\\rVert}{\\lVert y_t^{\\text{ref}}\\rVert},\\quad \\varepsilon_{\\text{sep}}=\\frac{1}{|\\mathcal{D}|}\\sum_{t\\in\\mathcal{D}}\\frac{\\lVert y_t^{\\text{sep}}-y_t^{\\text{ref}}\\rVert}{\\lVert y_t^{\\text{ref}}\\rVert}$$</div>\n<p>其中 $\\mathcal{D}$ 为 decode token 集合，$y^{\\text{mix}}$ 为混批输出，$y^{\\text{sep}}$ 为 decode 单独成批输出。若 $\\varepsilon_{\\text{mix}}$ 显著高于 $\\varepsilon_{\\text{sep}}$，说明干扰来自拼批而非量化格式。这个比对本身要花一次额外前向，属于诊断态开销，不能常驻；生产上退化为抽样探针，每 N 个调度步抽一个 decode 批次做分离复算。</p>\n\n<h3 id=\"alg-chunked-prefill-sec-40\">四十 · OOM：KV page 与临时缓冲的双重压力</h3>\n<p>混批的显存失败模式有两类，容易被混为一谈。第一类是 KV page 耗尽：预填 chunk 完成后 KV 写入 page，chunk 越大，单步写入的 page 数越多，page 池的瞬时水位抬升越陡；当预填队列深、decode 请求的 KV 又在持续增长时，page 池会在某个调度步被预填写入顶到上限，触发抢占或直接 OOM。第二类是临时缓冲膨胀：统一批次的 MoE dispatch 缓冲、attention 的 mask 与 gather 索引缓冲都按 $B_{\\text{step}}=B_{\\text{decode}}+c_{\\text{chunk}}$ 分配，chunk 标定过大时这些缓冲随批次线性增长，而它们不在 KV page 池的核算范围内，监控面板上表现为“KV 还有余量但分配失败”。诊断要区分这两类：看 OOM 发生时刻的 page 池水位与临时缓冲峰值，若 page 池接近满则是第一类，若 page 池有余而分配器报错则是第二类。回滚手段不同——第一类要降 chunk size 或给预填队列设深度上限，第二类要改缓冲池的预分配策略、按 $B_{\\text{decode}}$ 与 $c_{\\text{chunk}}$ 分别核算峰值而非按最坏情况静态预留。代价上，静态预留最坏情况会浪费显存、压低可容纳的并发 decode 数；动态扩容则引入分配抖动，在尾延迟上体现为偶发的长尾调度步。</p>\n\n<h3 id=\"alg-chunked-prefill-sec-41\">四十一 · 批抖动与路由不均：从 TPOT 方差定位到专家热点</h3>\n<p>批抖动的表征是 TPOT 的方差而非均值抬升。混批下每个调度步的组成不同：decode 批次随请求进出波动，预填 chunk 固定但队列深度变化，于是 $B_{\\text{step}}$ 逐 step 变化，MoE 路由分布也随之逐 step 变化。诊断的第一步是把 TPOT 按调度步拆开，看方差是来自 $B_{\\text{decode}}$ 的波动还是来自路由偏斜。路由偏斜的判据是热点专家的容量溢出计数：预填 token 与 decode token 混合 dispatch 后，若某几个专家在多数调度步都接近容量上限，溢出概率随 chunk 增大而上升，触发 token 丢弃或排队，表现为该 step 的 MoE 层耗时尖刺。这里要区分两种抖动源：容量因子路由造成的丢弃是策略性丢弃（属于路由设计，另有条目讨论），而混批造成的偏斜是负载形态变化引起的，前者调容量因子，后者调 chunk size 或做预填与 decode 的分组 dispatch。监控上要按来源分别统计专家命中直方图，把预填 token 的专家分布与 decode token 的专家分布分开看——若两者分布差异大，混批就是把两个不同的热点叠在一起，专家并行的 All-to-All 通信量随之放大。回滚路径是先降 chunk size 缩小预填注入量，再考虑把预填 chunk 拆成多个更小的 dispatch 组以打散热点。</p>\n<div class=\"formula\">$$\\text{Var}(\\text{TPOT})\\approx \\text{Var}\\!\\left(\\frac{T_{\\text{step}}(B_{\\text{decode}},c_{\\text{chunk}})}{n_{\\text{dec}}}\\right),\\quad T_{\\text{step}}\\approx\\max\\left(\\frac{B_{\\text{dec}}N_{\\text{kv}}}{\\text{BW}},\\ \\frac{B_{\\text{dec}}+C_{\\text{chunk}}}{\\text{FLOPs}_{\\text{peak}}}\\right)$$</div>\n<p>这个式子说明抖动的两个来源：$B_{\\text{decode}}$ 波动改变带宽项，$c_{\\text{chunk}}$ 固定但 $B_{\\text{decode}}$ 变化时算力项的相对占比变化，两者共同决定 $T_{\\text{step}}$ 的分布。工程判断是：当带宽项主导时，降 chunk 对 TPOT 方差改善有限；当算力项主导时，chunk 是主要杠杆。</p>\n\n<h3 id=\"alg-chunked-prefill-sec-42\">四十二 · 尾延迟尖刺：chunk 边界与调度步对齐</h3>\n<p>尾延迟尖刺在混批里有一个特有的来源：chunk 边界与调度步的对齐。预填请求按 512 token 切分，最后一个 chunk 往往不足 512，若调度器按固定 chunk 注入，末尾的小 chunk 会造成某些 step 的 $B_{\\text{step}}$ 突然变小，GPU 利用率塌陷，紧接着下一个长预填请求的首个满 chunk 又把 $B_{\\text{step}}$ 顶高，形成“小步—大步”交替的锯齿。这种锯齿在 P99 上表现为周期性的尖刺，周期等于预填队列的周转时间。诊断方法是记录每步的 $B_{\\text{step}}$ 与 $c_{\\text{chunk}}$ 实际值，看尖刺是否与 chunk 尾块或队列切换时刻重合。另一类尖刺来自预填 chunk 完成时的 KV 写入：chunk 完成后一次性写入 page，写入量与 chunk 大小成正比，若与 decode 的 KV gather 撞在同一 step 的显存事务上，会造成带宽争用。缓解手段是把 KV 写入拆到多个 step 分摊，或把写入排在 decode gather 之后的独立小步，代价是预填完成到可被 decode 可见之间多一个 step 的延迟，对 TTFT 有轻微影响但对 TPOT 尾部分布更友好。回滚判据是：若 P99 尖刺幅度超过 SLO 余量的固定比例且与 chunk 尾块强相关，优先改切分策略（尾块合并或补齐）而非整体降 chunk size。</p>\n\n<h3 id=\"alg-chunked-prefill-sec-43\">四十三 · 监控面与回滚闸门</h3>\n<p>监控要覆盖四个面，且每个面都按来源（预填/解码）拆分。调度面：每步的 $B_{\\text{decode}}$、$c_{\\text{chunk}}$、预填队列深度、chunk 尾块比例。显存面：KV page 池水位、临时缓冲峰值、page 写入速率。路由面：按来源的专家命中直方图、容量溢出计数、All-to-All 通信量。延迟面：TTFT 与 TPOT 的分位数，尤其是 P99 与方差。这四个面要能在一个调度步的粒度上对齐，否则无法把尖刺归因到具体机制。回滚闸门按代价从低到高排：第一档调 chunk size（只改调度参数，不重启）；第二档改切分策略与尾块处理（改调度器逻辑）；第三档给预填队列设深度上限或对预填做准入限流（牺牲部分 TTFT 换 TPOT 稳定）；第四档退回预填解码分离部署（资源隔离，但放弃共享权重读取带来的带宽摊薄）。闸门触发条件应绑定 SLO 的具体分位数而非均值，因为混批的失败几乎都先体现在尾部。工程判断落在一点：chunk size 是这套机制唯一的连续调节旋钮，但它同时影响 TTFT、TPOT 方差、路由偏斜与显存水位四个目标，所以标定不能一次定死，要按负载形态（长预填占比、decode 并发数）分档配置，并在监控里保留按档位回溯的能力。</p>\n<table class=\"mini\"><thead><tr><th>失败模式</th><th>可观测信号</th><th>首选回滚</th><th>代价</th></tr></thead><tbody><tr><td>混批精度漂移</td><td>decode 逐 token 相对误差系统性抬升</td><td>按来源分组微缩放</td><td>每组多一次 scale 归约</td></tr><tr><td>KV page 耗尽</td><td>page 池水位贴顶、抢占计数上升</td><td>降 chunk 或限预填队列深度</td><td>TTFT 变长</td></tr><tr><td>临时缓冲 OOM</td><td>page 有余而分配失败</td><td>按来源分别核算缓冲峰值</td><td>分配抖动、尾延迟长尾</td></tr><tr><td>路由偏斜</td><td>热点专家溢出计数随 chunk 上升</td><td>降 chunk 或分组 dispatch</td><td>通信量放大或利用率下降</td></tr><tr><td>尾延迟尖刺</td><td>P99 与 chunk 尾块/队列切换重合</td><td>尾块合并或 KV 写入分摊</td><td>TTFT 轻微增加</td></tr></tbody></table>\n<p>这张表的作用是把“症状—信号—动作”绑定，避免在尾延迟尖刺出现时误调容量因子或误判为量化问题。每个动作都对应一个可量化的代价项，回滚决策就是在这些代价项与 SLO 余量之间做取舍，而不是追求单点最优。</p>\n\n<h3 id=\"alg-chunked-prefill-sec-44\">四十四 · 混批的失效边界：从路由偏斜到 chunk 标定失准</h3>\n<p>这套方案没有资源隔离这道保险，预填与解码共享同一次前向和同一份专家权重，因此所有失效都从“共享”二字长出来。最隐蔽的一类不是崩溃，而是精度与语义的错位：统一批次里预填 token 走因果 mask、decode token 走 KV gather，输出必须按来源严格拆分。一旦拆分边界与 page 写入时机错位——例如某个预填 chunk 的 KV 尚未落 page，而同批 decode 已按新 page 表 gather——就会出现读到半写 page 的静默错误，表现为个别请求输出重复或截断，监控上只看到 perplexity 轻微漂移而非报错。诊断手段是给每个 token 打来源标签并在 attention 输出处做一致性校验：预填 token 的 logits 只用于写 KV，decode token 的 logits 才进采样器，两条路径的 hidden state 若在同一 batch 内被错误复用，校验会立刻暴露。代价是每步多一次轻量比对，相对一次前向可忽略，但它把一类不可见的精度事故变成了可断言的失败。</p>\n<p>第二类是容量型失效，直接由混批的路由偏斜触发。预填 chunk 的 token 分布与 decode token 分布天然不同：预填是成段的连续文本，decode 是逐 token 自回归，两者混在一个批次里过 MoE 层时，路由按 token 独立计算，合并后的专家命中分布比纯 decode 批次更尖。热点专家的容量上限被击穿后，token 要么被丢弃重排、要么在专家并行组内排队，后者直接放大 all-to-all 通信量。可用的判据是把单步时间写成</p>\n<div class=\"formula\">$$T_{\\text{step}}\\approx\\max\\left(\\frac{B_{\\text{dec}}N_{\\text{kv}}}{\\text{BW}},\\ \\frac{B_{\\text{dec}}+C_{\\text{chunk}}}{\\text{FLOPs}_{\\text{peak}}}\\right),\\quad \\text{TPOT}\\le \\frac{T_{\\text{step}}}{\\text{tokens/step}}$$</div>\n<p>其中 $B_{\\text{step}} = B_{\\text{decode}} + c_{\\text{chunk}}$。当 $c_{\\text{chunk}}$ 标定过大，算力项压过带宽项，TPOT 被预填拖慢，长预填仍会周期性击穿延迟 SLO；当 $c_{\\text{chunk}}$ 过小，预填 kernel launch 开销占比升高，调度步数增多而每步有效 token 减少，GPU 利用率与 TTFT 同时恶化。512 token 这个示例值只是起点，真正的标定要按 SLO 反解：给定 TPOT 上限与 decode 批次规模，算出 $c_{\\text{chunk}}$ 的可行区间，再在区间内取使专家命中熵最大的点。</p>\n<table class=\"mini\"><thead><tr><th>失效模式</th><th>可观测信号</th><th>处置</th></tr></thead><tbody><tr><td>chunk 过大</td><td>TPOT 周期性尖刺、预填队列清空后回落</td><td>下调 chunk，或对长预填加步数配额</td></tr><tr><td>chunk 过小</td><td>步数上升、每步 token 数下降、TTFT 恶化</td><td>上调 chunk 并合并相邻预填 chunk</td></tr><tr><td>路由偏斜</td><td>热点专家排队时长、all-to-all 字节数上升</td><td>限制单步预填 token 占比，或按专家容量反推 chunk 上限</td></tr><tr><td>page 写入错位</td><td>输出重复/截断、perplexity 漂移</td><td>来源标签校验，失败即回滚到预填独占模式</td></tr></tbody></table>\n<p>第三类是尾延迟尖刺与回滚判断。混批方案的尾延迟不是平滑分布，而是与预填队列长度耦合的阶跃：队列非空时每步都背着一个 chunk，队列清空瞬间 TPOT 骤降，随后新长预填到达又骤升，监控上表现为与请求到达相关的周期性尖刺。诊断应盯三个量——预填队列深度、单步实际 $c_{\\text{chunk}}$ 与标定值的偏差、专家并行组内最长排队时间——任一越界即触发降级。回滚路径要预先设计成两级：一级把 chunk 缩到下限并暂停新预填入队，让 decode 批次独占若干步以吸收积压；二级整体退回整段预填独占模式，牺牲 TTFT 换 TPOT 稳定。回滚的代价必须量化：退回独占模式意味着 decode 重新被长预填饿死，TTFT 与 TPOT 回到不可兼得的状态，因此回滚阈值应设在“尾延迟尖刺已击穿 SLO 且持续超过一个预填 chunk 的完成周期”，而不是单次尖刺。这套方案的规模上限不在算力，而在热点专家容量与 chunk 标定精度：前者决定混批能承受多大的路由偏斜，后者决定 TPOT 与 TTFT 能否同时守住。</p>\n<h3 id=\"alg-chunked-prefill-sec-45\">四十五 · 同族谱系：三条路线与一个共同分母</h3>\n<p>分块预填与解码 piggyback 不是孤立技巧，它处在一个三选一的决策面上：整段预填独占、预填解码分离部署、以及本片段的混批 piggyback。三者的共同分母是同一个约束——预填是算力密集、解码是带宽密集，二者若在同一时间片上争夺同一批 SM 与同一份权重，干扰不可避免；区别只在于把干扰关进哪个笼子。整段预填独占把干扰变成时间上的串行，用 decode 的饥饿换取预填的干净；分离部署把干扰变成空间上的隔离，用两份权重与两套 KV 页换资源独立；piggyback 把干扰变成批次内的配额，用 chunk size 给预填 token 数设上限，让两类 token 共享一次前向。因此选型的第一问不是“哪个快”，而是“你的 SLO 里 TTFT 与 TPOT 谁更紧、GPU 池是否允许翻倍”。</p>\n<p>把三条路线的单步代价写成同一形式便于对照。piggyback 的步时由前文给出的关系约束：</p>\n<div class=\"formula\">$$T_{\\text{step}}\\approx\\max\\left(\\frac{B_{\\text{dec}}N_{\\text{kv}}}{\\text{BW}},\\ \\frac{B_{\\text{dec}}+C_{\\text{chunk}}}{\\text{FLOPs}_{\\text{peak}}}\\right),\\quad \\text{TPOT}\\le \\frac{T_{\\text{step}}}{\\text{tokens/step}}$$</div>\n<p>其中 $B_{\\text{step}} = B_{\\text{decode}} + c_{\\text{chunk}}$ 是拼批后的总 token 数。整段独占相当于 $c_{\\text{chunk}}$ 取整个预填长度，第二项被撑爆，TPOT 在预填窗口内失去上界；分离部署相当于把 $B_{\\text{decode}}$ 与 $c_{\\text{chunk}}$ 放进两个独立实例，各自套用上式，代价是权重与 KV 页各存一份。piggyback 的独特之处是 $c_{\\text{chunk}}$ 成为一个可标定旋钮：材料给出的示例值是 512 token，它直接决定预填对 decode 的干扰上限。举例而言，当 decode 批次为数百 token 量级时，512 的 chunk 使预填项在步时中占比可控；若把 chunk 抬到数千，第二项迅速压过第一项，decode 的 TPOT 被预填算力拖慢，这正是前文失败模式里“长预填周期性击穿延迟 SLO”的来源。</p>\n\n<h3 id=\"alg-chunked-prefill-sec-46\">四十六 · 决策表：四个判据与三档结论</h3>\n<p>选型可以压缩成四个判据，每个判据都能从可用事实中读出方向，而不需要实验数字。判据一，TTFT 与 TPOT 是否必须同时满足：若只有 TTFT 有硬约束、decode 可以容忍抖动，整段独占最省工程；若两者同时进 SLO，piggyback 与分离部署都成立，但 piggyback 不需要额外 GPU。判据二，GPU 池是否允许按角色拆分：分离部署要求预填池与解码池各自独立扩缩，材料明确指出 piggyback 不拆分 GPU 池、共享同一前向与同一份专家权重，这是它在集群预算紧张时的唯一优势来源。判据三，MoE 路由偏斜能否被容量吸收：piggyback 混批后预填 token 与 decode token 的路由分布叠加，热点专家容量溢出概率上升，若模型专家粒度粗、热点集中，这一项会成为规模上限；分离部署则把两类 token 的路由分布分置于不同实例，偏斜不叠加。判据四，chunk 标定的人力与观测成本：piggyback 的 chunk size 必须按 SLO 精细标定，过小则 kernel launch 开销占比升高、调度步数增多而每步有效 token 减少，过大则 decode 被拖慢，两端都会同时恶化 GPU 利用率与 TTFT。</p>\n<table class=\"mini\"><thead><tr><th>判据</th><th>整段预填独占</th><th>预填解码分离部署</th><th>分块预填 piggyback</th></tr></thead><tbody>\n<tr><td>TTFT/TPOT 同时约束</td><td>不满足，decode 饥饿</td><td>满足，各自独立调优</td><td>满足，靠 chunk 配额</td></tr>\n<tr><td>GPU 池</td><td>单池，最省卡</td><td>双池，权重与 KV 页各一份</td><td>单池，共享前向与专家权重</td></tr>\n<tr><td>MoE 路由偏斜</td><td>不叠加，但预填窗口内 decode 无路由</td><td>不叠加，分布分置</td><td>叠加，热点专家容量成上限</td></tr>\n<tr><td>标定成本</td><td>低</td><td>中，需两套容量规划</td><td>高，chunk 需按 SLO 精细标定</td></tr>\n<tr><td>典型适用</td><td>离线批推理、TTFT 单目标</td><td>在线服务、双 SLO 且集群富裕</td><td>在线服务、双 SLO 且集群紧张</td></tr>\n</tbody></table>\n<p>把表读成决策树：先问双 SLO 是否同时硬约束，否则整段独占；再问集群是否允许双池，允许则分离部署，不允许则 piggyback；最后问 MoE 热点专家容量是否足够吸收叠加偏斜，不足则回到分离部署或降低 chunk。这张表的价值在于它把“哪个算法更好”翻译成“你的约束落在哪一格”，而不是给出普适排序。</p>\n\n<h3 id=\"alg-chunked-prefill-sec-47\">四十七 · 与分离部署的边界：共享前向的收益与代价</h3>\n<p>piggyback 相对分离部署的收益可以写成一次权重读取被两类 token 共同摊薄：MoE 专家权重带宽是解码侧最贵的资源，混批让预填 token 顺路搭上 decode 已经付出的权重读取，材料把这表述为“预填与解码共享一次权重读取以摊薄专家权重带宽”。代价则落在路由侧：路由按 token 独立计算，预填 token 与 decode token 混合 dispatch，两类分布叠加后热点专家更容易溢出，触发 token 丢弃或排队，混合 dispatch 的负载不均还会放大专家并行通信开销。因此这条边界不是“谁更快”，而是“摊薄的带宽收益能否覆盖叠加的偏斜代价”。</p>\n<p>一个可操作的判断是看热点专家的容量余量。设某热点专家在 decode 单独运行时的负载为 $L_{\\text{dec}}$，预填 chunk 注入后叠加为 $L_{\\text{dec}} + L_{\\text{pre}}$，容量因子为 $F$，则不发生溢出的条件是 $L_{\\text{dec}} + L_{\\text{pre}} \\le F\\cdot L_{\\text{cap}}$。chunk size 正是控制 $L_{\\text{pre}}$ 的唯一旋钮：把 512 token 的 chunk 减半，$L_{\\text{pre}}$ 减半，溢出概率下降，但调度步数翻倍、kernel launch 开销占比上升。这条不等式解释了为什么 piggyback 的规模上限是热点专家容量而非显存或带宽——容量因子路由与令牌丢弃那一条目已从路由侧展开，此处只把它当作 piggyback 的约束边界引用。工程上的做法是把 chunk size 标定到“热点专家刚好不溢出”的位置，而不是标定到“decode 刚好不被拖慢”的位置，因为后者通常更宽松，前者才是真正的瓶颈。</p>\n\n<h3 id=\"alg-chunked-prefill-sec-48\">四十八 · 与整段独占的边界：时间片串行 vs 批次内配额</h3>\n<p>整段预填独占的本质是把干扰外化为时间：预填窗口内 decode 完全不调度，窗口结束后 decode 集中补发。它的代价是 TPOT 抖动呈方波形态，长预填越长，方波越宽，材料所述“长预填请求独占 GPU 造成 decode 请求被饿死”正是这一形态。piggyback 把方波换成锯齿：每个调度步都注入一个有上限的预填 chunk，decode 每步都被服务但每步都被轻微拖慢，TPOT 抖动幅度由 chunk size 决定而非由预填长度决定。因此两者的分界不在吞吐，而在抖动是否可被 SLO 容忍：若 SLO 只约束平均 TPOT 而不约束尾部，整段独占的方波可以被平均掉；若 SLO 约束 P99 TPOT，方波必然击穿，piggyback 的锯齿才是唯一可行形态。</p>\n<p>伪代码层面，两者的调度器只差一行。整段独占的调度循环是“若预填队列非空则整段执行预填，否则执行 decode 批次”；piggyback 的循环是“每步取 decode 批次加一个预填 chunk 拼批”。差别在于后者把预填队列的消费速率与 decode 的服务速率绑定在同一节拍上，预填队列清空的速度因此受 chunk size 与步频共同约束，TTFT 不再由单次预填时长决定，而由“预填总 token 数除以每步 chunk 数再乘以步时”决定。这给出一条直接的容量判断：若 TTFT 目标紧，应增大 chunk 而非减小，因为减小 chunk 会拉长预填队列的清空步数；但增大 chunk 又会压过 decode 批次，两端夹逼出 512 token 这一量级的示例值。材料未给出具体批大小与 SLO 数值，因此标定必须落在真实负载上做，而不是照搬示例。</p>\n\n<h3 id=\"alg-chunked-prefill-sec-49\">四十九 · 选型后的标定顺序与回退路径</h3>\n<p>选定 piggyback 之后，标定应按“先定 chunk 上限、再定 decode 批次下限、最后验路由偏斜”的顺序推进，而不是反过来。第一步用热点专家容量不等式定 chunk 上限：从 512 token 量级出发，向上试探直到热点专家溢出概率抬头，向下试探直到 kernel launch 开销占比可观测地升高，取两端之间的区间。第二步定 decode 批次下限：由步时公式的第一项可知，decode 批次过小时带宽项不足以摊薄权重读取，piggyback 的共享前向收益消失，此时应合并调度步或等待队列积累。第三步验路由偏斜：混批后按来源拆分输出、对预填 token 用因果 mask、对 decode token 用 KV gather，这一拆分本身不解决偏斜，只是避免 mask 混淆，偏斜仍需靠 chunk 上限压制。</p>\n<p>回退路径有两条，且都指向分离部署而非整段独占。第一条，当热点专家容量在 chunk 下限处仍然溢出，说明叠加偏斜已不可压缩，应拆池让两类分布分置；第二条，当 TTFT 目标要求 chunk 大于 decode 批次可承受的上限，说明单池内的配额已经无法同时满足双 SLO，同样应拆池。两条回退的共同点是：piggyback 的失败不是“算法错了”，而是“单池配额不够用了”，此时继续调 chunk 只会在两端失败模式之间来回震荡——过大拖慢 decode，过小抬高 launch 开销并恶化 TTFT。把回退条件写成可观测信号，比把 chunk size 写死更有工程价值：溢出计数、launch 开销占比、P99 TPOT 三者任一越界，即触发拆池评估。这也解释了为什么 piggyback 在集群富裕时应让位于分离部署——它的全部优势建立在“不拆池”之上，一旦拆池，共享前向的摊薄收益随之消失，继续混批只剩偏斜代价。</p>\n\n<h3 id=\"alg-chunked-prefill-sec-50\">五十 · 选型边界：piggyback 与整段预填、预填解码分离部署的三角权衡</h3>\n<p>把 piggyback 放进同族算法谱系，它占据的是“不拆池、靠时间切片控干扰”的中间位。与整段预填独占 GPU 相比，它用固定 chunk 把长预填切成可抢占的片段，decode 批次每步都能拿到一次前向机会，TPOT 抖动被压到由 chunk 大小决定的水平；与预填解码分离部署相比，它不划分 GPU 池、不做资源隔离，预填与解码共享同一份专家权重读取，代价是干扰只能靠调度参数约束而非硬件边界。选型的判据因此落在两件事上：SLO 是否同时硬约束 TTFT 与 TPOT，以及专家并行拓扑能否承受混批带来的路由偏斜。若 TPOT 是软目标而 TTFT 是硬约束，整段预填反而更省调度开销；若两者都硬且集群不允许拆池，piggyback 是唯一不引入额外 GPU 占用的选项；若热点专家容量本就紧张，分离部署用资源隔离换掉偏斜风险更稳。</p>\n<p>决策表按失效条件而非优点排列，因为这套方案的边界全在参数标定上：</p>\n<table class=\"mini\"><thead><tr><th>条件</th><th>选 piggyback</th><th>选整段预填</th><th>选分离部署</th></tr></thead><tbody><tr><td>TPOT 硬约束、TTFT 硬约束</td><td>是，chunk 双向调优</td><td>否，decode 被饿死</td><td>是，但需双池容量</td></tr><tr><td>集群不允许拆 GPU 池</td><td>是</td><td>是</td><td>否</td></tr><tr><td>热点专家容量接近饱和</td><td>谨慎，偏斜放大</td><td>是</td><td>是，隔离后偏斜不外溢</td></tr><tr><td>预填请求占比高、chunk 可切</td><td>是</td><td>否</td><td>是</td></tr></tbody></table>\n<p>chunk 标定的失效是双向的。单步预填 token 数一旦压过 decode 批次，公式 $T_{\\text{step}}\\approx\\max\\left(B_{\\text{dec}}N_{\\text{kv}}/\\text{BW},\\ (B_{\\text{dec}}+C_{\\text{chunk}})/\\text{FLOPs}_{\\text{peak}}\\right)$ 的第二项接管瓶颈，decode 的 TPOT 被预填算力拖慢，长预填仍会周期性击穿延迟 SLO；反之 chunk 过小，预填 kernel launch 开销占比升高，调度步数增多而每步有效 token 减少，GPU 利用率与 TTFT 同时恶化。512 token 只是起点，真实标定要沿 $B_{\\text{step}}=B_{\\text{decode}}+c_{\\text{chunk}}$ 扫描，找到 TPOT 上界与 launch 开销的交叉点。</p>\n<p>最易被低估的代价在 MoE 层：预填 token 与 decode token 混批后路由按 token 独立计算，两类分布叠加使路由更偏斜，热点专家容量溢出会触发 token 丢弃或排队，混合 dispatch 的负载不均进一步放大专家并行通信开销。这条链路决定了 piggyback 的规模上限不在 chunk 大小，而在热点专家的剩余容量——当偏斜概率随批内 token 构成漂移而上升时，再精细的 chunk 标定也救不回被专家排队吃掉的 TPOT。工程判断是：先测混批前后的专家命中分布，再决定是否值得用这份偏斜换掉拆池的容量成本。</p>\n<table class=\"mini\" data-fig=\"alg-quick\"><caption>速查：这一页回答的五件事</caption><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td>年份 · 方向</td><td>2023 · MoE路由与容量因子</td></tr><tr><td>解决什么</td><td>长预填请求独占 GPU 造成 decode 请求被饿死，TTFT 与 TPOT 无法同时满足；预填与解码混批时预填的算…</td></tr><tr><td>一句话机制</td><td>把长预填切成固定大小的 chunk，每个调度步把若干预填 chunk 与当前所有 decode 请求拼成一个批次，de…</td></tr><tr><td>代价与失效</td><td>预填 chunk 与 decode 混批使 MoE 路由分布更偏斜，热点专家容量溢出概率上升；chunk 过小则预填 kernel lau…</td></tr><tr><td>后继</td><td>tcgen05 分组 GEMM 专家批处理</td></tr></tbody></table>\n<p class=\"paper-line\">本页对应：algorithms/alg-chunked-prefill · 共 8 个片段</p>\n";break;}}})();
